window.GRILE_QUESTION_SHARDS=window.GRILE_QUESTION_SHARDS||{};window.GRILE_QUESTION_SHARDS["shard-119"]=[{"id":"set2-vCMGlUKv","fingerprint":"ff5c8cbd5e87beb1","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Care sunt particularitățile morfologice ale dinților permanenți imaturi (DPI) care cresc riscul de afectare carioasă?","options":[{"id":"A","text":"Camera pulpară de dimensiuni mari și coarnele pulpare apropiate de suprafață."},{"id":"B","text":"Pereții camerei pulpare îngroșați prin depunere de dentină secundară."},{"id":"C","text":"Morfologia ocluzală retentivă, în special la molari."},{"id":"D","text":"Dentină groasă cu canalicule dentinare înguste la erupție."},{"id":"E","text":"Prezența frecventă a defectelor de structură ale smalțului, precum hipoplaziile."}],"correct":["A","C","E"],"pages":[406],"source":"set-2"},{"id":"set2-L1WwPQv9","fingerprint":"4792f52aa8f6f4c6","chapterId":"set-2","subchapterId":"set2-5.04","type":"CS","text":"Ce caracteristică structurală definește smalțul și dentina unui dinte permanent imatur la momentul erupției?","options":[{"id":"A","text":"Dentina este subțire, cu canalicule dentinare largi ce îi cresc permeabilitatea."},{"id":"B","text":"Canaliculele dentinare sunt înguste, limitând pătrunderea monomerului din rășinile compozite."},{"id":"C","text":"Pulpa tânără are o capacitate redusă de apărare, procesele patologice fiind de obicei ireversibile."},{"id":"D","text":"Smalțul este complet maturat, oferind protecție maximă împotriva atacului acid."},{"id":"E","text":"Maturarea smalțului se încheie complet în momentul erupției."}],"correct":["A"],"pages":[406],"source":"set-2"},{"id":"set2-XuXAD13j","fingerprint":"d8cdc6e3a8cecbe1","chapterId":"set-2","subchapterId":"set2-5.04","type":"CS","text":"Care este durata aproximativă a procesului de maturare posteruptivă a smalțului la dinții permanenți imaturi?","options":[{"id":"A","text":"Este un proces care durează toată viața."},{"id":"B","text":"6 luni post-erupție."},{"id":"C","text":"1 an post-erupție."},{"id":"D","text":"Se finalizează în momentul atingerii planului de ocluzie."},{"id":"E","text":"2-3 ani post-erupție."}],"correct":["E"],"pages":[406],"source":"set-2"},{"id":"set2-NDV8MmJ1","fingerprint":"7110e7b223d271ef","chapterId":"set-2","subchapterId":"set2-5.04","type":"CS","text":"Cum se modifică distribuția leziunilor carioase între arcade odată cu înaintarea în vârstă la copiii cu dinți permanenți imaturi?","options":[{"id":"A","text":"Afectarea celor două arcade este simetrică și egală la toate grupele de vârstă."},{"id":"B","text":"Diferențele de afectare între cele două arcade se diminuează progresiv după vârsta de 10 ani."},{"id":"C","text":"După vârsta de 10 ani, frecvența leziunilor devine mai importantă la maxilar."},{"id":"D","text":"La vârste de 6-7 ani, dinții maxilari sunt mai grav afectați decât cei mandibulari."},{"id":"E","text":"Arcada mandibulară rămâne cea mai afectată pe toată perioada copilăriei."}],"correct":["C"],"pages":[406],"source":"set-2"},{"id":"set2-k1IVbVsF","fingerprint":"0aaf98c47174a58b","chapterId":"set-2","subchapterId":"set2-5.04","type":"CS","text":"Care dintre următoarele afirmații descrie corect diferențele de carioactivitate între sexe la dinții permanenți imaturi?","options":[{"id":"A","text":"La vârsta de 7 ani, diferențele de carioactivitate între sexe sunt foarte importante."},{"id":"B","text":"Nu există diferențe în ceea ce privește numărul de leziuni carioase între fete și băieți."},{"id":"C","text":"Diferențele între sexe sunt maxime la erupția primilor molari și apoi scad."},{"id":"D","text":"La 13 ani, fetele pot prezenta un plus de 1-2 suprafețe cariate comparativ cu băieții."},{"id":"E","text":"Băieții prezintă constant mai multe leziuni carioase decât fetele."}],"correct":["D"],"pages":[406],"source":"set-2"},{"id":"set2-6LH-XNkk","fingerprint":"f47fa719a0687336","chapterId":"set-2","subchapterId":"set2-5.04","type":"CS","text":"Care este ordinea descrescătoare corectă a vulnerabilității la carie pentru următoarele grupe de dinți permanenți?","options":[{"id":"A","text":"Primii molari, molarii secunzi, premolarii."},{"id":"B","text":"Molarii de minte, premolarii, primii molari."},{"id":"C","text":"Frontalii inferiori, canini, premolari."},{"id":"D","text":"Centralii superiori, primii molari, frontalii inferiori."},{"id":"E","text":"Premolari, primii molari, molarii secunzi."}],"correct":["A"],"pages":[406],"source":"set-2"},{"id":"set2-pC76K7Ez","fingerprint":"c1c4ca8568fdc53e","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Care dintre următoarele afirmații descriu caracteristicile afectării prin carie la dinții permanenți imaturi?","options":[{"id":"A","text":"Răspândirea cariei se face simetric între partea stângă și dreaptă."},{"id":"B","text":"Leziunile carioase apar frecvent în oglindă."},{"id":"C","text":"Pulpa tânără are o mare putere de apărare, favorizând reversibilitatea proceselor patologice inițiale."},{"id":"D","text":"Frontalii inferiori și caninii sunt, cu excepția cazurilor de carioactivitate intensă, foarte vulnerabili la carie."},{"id":"E","text":"Permeabilitatea crescută a dentinei imature este valabilă doar pentru germenii microbieni, nu și pentru materiale dentare."}],"correct":["A","B"],"pages":[406],"source":"set-2"},{"id":"set2-HbjryilK","fingerprint":"fc3c0ca0040afb4d","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Datorită căror caracteristici este crescută permeabilitatea dentinei la dinții permanenți imaturi și ce consecințe are acest fapt?","options":[{"id":"A","text":"Dentina este groasă, cu canalicule dentinare înguste la erupție."},{"id":"B","text":"Este permeabilă pentru Ca(OH)₂ și monomerul din rășinile compozite."},{"id":"C","text":"Permeabilitatea crescută favorizează progresia rapidă a cariei spre camera pulpară."},{"id":"D","text":"Pulpa tânără nu poate contracara efectele permeabilității crescute."},{"id":"E","text":"Permeabilitatea scade pe măsură ce se depune dentină secundară în procesul de maturare."}],"correct":["B","C","E"],"pages":[406],"source":"set-2"},{"id":"set2-8Uqwg4EX","fingerprint":"e05457cc1ecc4940","chapterId":"set-2","subchapterId":"set2-5.04","type":"CS","text":"Conform clasificării după profunzime, cum este definită o carie simplă medie la dinții permanenți imaturi (DPI)?","options":[{"id":"A","text":"Se extinde în smalț și maxim 0,5 mm în dentină."},{"id":"B","text":"Distanța de la leziune până la camera pulpară este de sub 0,5 mm."},{"id":"C","text":"Este localizată între 0,5 mm peste jonțiunea smalț-dentină și până la 0,5 mm de pulpă."},{"id":"D","text":"Depășește jumătate din grosimea smalțului, fiind vizibilă pe radiografia bite-wing."},{"id":"E","text":"Afectează doar șanțurile și fosetele, fără a depăși joncțiunea smalț-dentină."}],"correct":["C"],"pages":[407],"source":"set-2"},{"id":"set2-FkOUDGJl","fingerprint":"e818170cdf9113aa","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Care dintre următoarele sunt clasificate ca forme de carie simplă cavitară la dinții permanenți imaturi (DPI)?","options":[{"id":"A","text":"Caria necavitară a smalțului suprafețelor netede (caria incipientă)."},{"id":"B","text":"Caria cronică."},{"id":"C","text":"Caria necavitară a smalțului de pe suprafețele accidentate (ocluzale)."},{"id":"D","text":"Caria avansată în dentină."},{"id":"E","text":"Caria cavitară a smalțului."}],"correct":["D","E"],"pages":[407],"source":"set-2"},{"id":"set2-jDf8E_WA","fingerprint":"d175adf90be6caa2","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Ce semne clinice pot fi identificate la examenul obiectiv al unei carii necavitare a smalțului pe suprafețele netede (carie incipientă)?","options":[{"id":"A","text":"Se observă o cavitate mică, dar detectabilă doar la palparea cu sonda ascuțită."},{"id":"B","text":"La inspecție, se observă o pată albă cretoasă, cel mai frecvent la nivelul coletului."},{"id":"C","text":"Transiluminarea simplă sau cu fibră optică poate evidenția leziunea incipientă."},{"id":"D","text":"Percuția în ax este de obicei pozitivă, indicând iritație pulpară."},{"id":"E","text":"Palparea blândă cu o sondă rotunjită relevă un smalț rugos în cazul unei leziuni active."}],"correct":["B","C","E"],"pages":[407],"source":"set-2"},{"id":"set2-nRQij_aJ","fingerprint":"4193060518dee3f7","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Care este mecanismul specific de debut pentru caria necavitară a smalțului de pe suprafețele accidentate (ocluzale)?","options":[{"id":"A","text":"Începe ca o singură leziune la baza șanțului care se extinde ulterior spre pereții laterali."},{"id":"B","text":"Debutează prin două leziuni separate pe pereții laterali ai șanțului sau fosetei."},{"id":"C","text":"Se manifestă inițial ca o modificare de culoare la baza șanțului, vizibilă doar cu magnificație."},{"id":"D","text":"Se dezvoltă uniform pe toată suprafața ocluzală, similar cu caria de pe suprafețele netede."},{"id":"E","text":"Leziunile separate de pe pereții laterali confluează după ce ajung la joncțiunea smalț-dentină."}],"correct":["B","E"],"pages":[407],"source":"set-2"},{"id":"set2-UrEPe-BD","fingerprint":"819eb7ea1a9b57f9","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Ce consecință poate avea utilizarea unei sonde ascuțite la palparea unei carii necavitare ocluzale?","options":[{"id":"A","text":"Poate distruge smalțul superficial și inocula germeni microbieni în leziune."},{"id":"B","text":"Creează o cavitate mică, ireversibilă."},{"id":"C","text":"Poate lustrui suprafața smalțului, mascând aspectul cretos al leziunii."},{"id":"D","text":"Nu are nicio consecință negativă, fiind o manevră standard de diagnostic."},{"id":"E","text":"Poate împinge resturi alimentare în profunzimea șanțului, fără a afecta smalțul."}],"correct":["A","B"],"pages":[407],"source":"set-2"},{"id":"set2-7Rw10Xxf","fingerprint":"e838ae2f6ddcea05","chapterId":"set-2","subchapterId":"set2-5.04","type":"CS","text":"În ce condiții examenul radiologic bite-wing poate evidenția cariile incipiente?","options":[{"id":"A","text":"Pentru orice carie incipientă de tip pată albă cretoasă, indiferent de localizare."},{"id":"B","text":"Când acestea sunt localizate pe suprafețele ocluzale și afectează doar versanții șanțului."},{"id":"C","text":"Doar în cazul cariilor incipiente inactive, cu suprafața lucioasă."},{"id":"D","text":"Atunci când leziunea a ajuns la joncțiunea smalț-dentină, indiferent de localizare."},{"id":"E","text":"Atunci când sunt localizate proximal și depășesc jumătate din grosimea smalțului."}],"correct":["E"],"pages":[407],"source":"set-2"},{"id":"set2-nNpPqxhW","fingerprint":"7190aa5938ca9cc2","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Care dintre următoarele semne și simptome sunt caracteristice cariei avansate în dentină?","options":[{"id":"A","text":"Testele de vitalitate sunt, de regulă, negative."},{"id":"B","text":"La inspecție, se observă o deschidere mică în suprafață cu o bază largă a leziunii."},{"id":"C","text":"Durere provocată de agenți fizici (rece) care persistă după îndepărtarea excitantului."},{"id":"D","text":"Papilele gingivale adiacente pot fi tumefiate și congestionate."},{"id":"E","text":"Camera pulpară este închisă la palparea cu sonda."}],"correct":["D","E"],"pages":[408],"source":"set-2"},{"id":"set2-ASGbWDwq","fingerprint":"914abc3d06979f52","chapterId":"set-2","subchapterId":"set2-5.04","type":"CS","text":"Ce aspect clinic al dentinei alterate este specific cariei acute avansate?","options":[{"id":"A","text":"Prezența unei pete albe cretoase la suprafața smalțului."},{"id":"B","text":"Aspect umed, de culoare alb-gălbuie."},{"id":"C","text":"Aspect dur la palpare cu sonda."},{"id":"D","text":"O modificare de culoare a dintelui în brun, vizibilă sub creasta marginală."},{"id":"E","text":"Aspect uscat, de culoare brun-maronie."}],"correct":["B"],"pages":[408],"source":"set-2"},{"id":"set2-f0jCDvW8","fingerprint":"7330c2df55438bf1","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Cu ce afecțiuni se face diagnosticul diferențial al cariei simple la dinții permanenți imaturi?","options":[{"id":"A","text":"Parodontita apicală acută."},{"id":"B","text":"Caria complicată."},{"id":"C","text":"Amelogeneza imperfectă."},{"id":"D","text":"Fracturile coronare nepenetrante."},{"id":"E","text":"Uzura dentară."}],"correct":["B","D","E"],"pages":[408],"source":"set-2"},{"id":"set2-uHpo8esL","fingerprint":"ca9587ddc93b7915","chapterId":"set-2","subchapterId":"set2-5.04","type":"CS","text":"Ce relevă examenul obiectiv în cazul unei carii cavitare a smalțului?","options":[{"id":"A","text":"Agățarea sondei la palpare."},{"id":"B","text":"Sângerări la nivelul papilelor dentare la palpare."},{"id":"C","text":"Prezența unei cantități mari de dentină alterată."},{"id":"D","text":"Răspuns pozitiv la percuția în ax."},{"id":"E","text":"Necesitatea efectuării de teste de vitalitate."}],"correct":["A"],"pages":[408],"source":"set-2"},{"id":"set2-Uubu2RIf","fingerprint":"b0a4488530113c13","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Care sunt obiectivele principale ale tratamentului cariei simple la dinții permanenți imaturi?","options":[{"id":"A","text":"Păstrarea vitalității pulpare pentru continuarea proceselor de apexogeneză și maturogeneză."},{"id":"B","text":"Amânarea tratamentului până la finalizarea apexogenezei."},{"id":"C","text":"Conservarea cât mai mare a structurilor dure dentare sănătoase."},{"id":"D","text":"Prevenirea apariției complicațiilor locale și la distanță."},{"id":"E","text":"Îndepărtarea completă a smalțului subminat, chiar dacă este sănătos."}],"correct":["A","C","D"],"pages":[408],"source":"set-2"},{"id":"set2-GyGg_mEB","fingerprint":"9375bfad74ee5639","chapterId":"set-2","subchapterId":"set2-5.04","type":"CS","text":"În ce context este menționată enameloplastia ca opțiune terapeutică?","options":[{"id":"A","text":"În contextul unui tip de carie unde examenul radiologic nu este util și percuția în ax este negativă."},{"id":"B","text":"În tratamentul cariei avansate în dentină, pentru a îndepărta dentina alterată de aspect uscat, brun-maroniu."},{"id":"C","text":"Ca metodă de diagnostic diferențial cu hipomineralizarea smalțului."},{"id":"D","text":"Pentru tratamentul cariei cavitare a smalțului, când palparea cu sonda agață."},{"id":"E","text":"Ca prim pas în tratamentul de urgență al cariei complicate."}],"correct":["A"],"pages":[408],"source":"set-2"},{"id":"set2-qYaMkgdo","fingerprint":"37f988eb75a12682","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Care sunt particularitățile morfo-structurale ale dinților permanenți tineri (DPI) care impun considerații speciale în tratamentul cariei simple?","options":[{"id":"A","text":"Capacitate redusă de apărare și vindecare a pulpei."},{"id":"B","text":"Canalicule dentinare largi și cameră pulpară mare."},{"id":"C","text":"Necesitatea aplicării tardive a metodelor de profilaxie."},{"id":"D","text":"Smalț și dentină poroase, imature."},{"id":"E","text":"Rădăcini complet formate și apex închis."}],"correct":["B","D"],"pages":[409],"source":"set-2"},{"id":"set2-goH_ifIa","fingerprint":"1aec763976084ae4","chapterId":"set-2","subchapterId":"set2-5.04","type":"CS","text":"Ce abordare terapeutică este recomandată pentru molarii cu sistem fisural demineralizat sau marmorat, la un pacient pediatric cu risc mic la carie?","options":[{"id":"A","text":"Tratament chirurgical prin prepararea unei cavități clasice."},{"id":"B","text":"Efectuarea sigilării simple."},{"id":"C","text":"Prepararea unei cavități clasa I ultraconservatoare."},{"id":"D","text":"Aplicarea tehnicii ART (Atraumatic Restorative Treatment)."},{"id":"E","text":"Amânarea oricărui tratament și monitorizare periodică."}],"correct":["B"],"pages":[409],"source":"set-2"},{"id":"set2-sF6ZNL29","fingerprint":"4328fc06bd38d6ed","chapterId":"set-2","subchapterId":"set2-5.04","type":"CS","text":"Care este principiul fundamental în prepararea cavităților la dinții permanenți tineri (DPI)?","options":[{"id":"A","text":"Îndepărtarea completă a dentinei alterate în toate situațiile."},{"id":"B","text":"Economia de substanță dentară sănătoasă."},{"id":"C","text":"Crearea unei cavități retentive pentru materialele de obturație."},{"id":"D","text":"Extensia preventivă în toate șanțurile și fosetele."},{"id":"E","text":"Aplicarea strictă a principiilor lui Black."}],"correct":["B"],"pages":[409],"source":"set-2"},{"id":"set2-O3mLEG3d","fingerprint":"65429496cd65309a","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Care dintre următoarele situații clinice reprezintă indicații pentru prepararea unei cavități clasa I ultraconservatoare?","options":[{"id":"A","text":"Pacienți cu risc mediu sau mare la carie."},{"id":"B","text":"Carii simple foarte profunde cu risc de deschidere pulpară."},{"id":"C","text":"Carii cavitare ocluzale minime în smalț."},{"id":"D","text":"Marmorații ocluzale la pacienți cu risc mic la carie."},{"id":"E","text":"Leziuni ale suprafețelor accidentate suspecte de a ascunde carii dentinare."}],"correct":["A","C","E"],"pages":[409],"source":"set-2"},{"id":"set2-hjxPFlcS","fingerprint":"f5e622e4518e37ed","chapterId":"set-2","subchapterId":"set2-5.04","type":"CS","text":"Ce tehnică specifică de tratament este indicată pentru copiii și adolescenții necooperanți de orice vârstă, cu sau fără dizabilități?","options":[{"id":"A","text":"Tehnica excavației succesive."},{"id":"B","text":"Tehnica clasică modificată."},{"id":"C","text":"Tehnica ART (Atraumatic Restorative Treatment)."},{"id":"D","text":"Tehnica minim-invazivă."},{"id":"E","text":"Sigilarea preventivă."}],"correct":["C"],"pages":[409],"source":"set-2"},{"id":"set2-w9_NTpVf","fingerprint":"0d7124049fca28b3","chapterId":"set-2","subchapterId":"set2-5.04","type":"CS","text":"În contextul tratamentului cariei simple la dinții permanenți tineri, ce presupune modificarea principiului exerezei totale a dentinei alterate?","options":[{"id":"A","text":"Se aplică doar la pacienții necooperanți, folosind tehnica ART."},{"id":"B","text":"Lăsarea unei cantități mari de dentină alterată în toate cariile profunde."},{"id":"C","text":"Realizarea unei pulpectomii parțiale ca măsură de precauție."},{"id":"D","text":"Înlocuirea exerezei cu aplicarea exclusivă de preparate fluorurate."},{"id":"E","text":"Aplicarea unui coafaj natural și utilizarea tehnicii excavației succesive."}],"correct":["E"],"pages":[409],"source":"set-2"},{"id":"set2-3KmhsY0Z","fingerprint":"c0f411dbe0963e8e","chapterId":"set-2","subchapterId":"set2-5.04","type":"CS","text":"Ce concept a fost înlocuit de principiul sigilării preventive în abordarea modernă a cavităților de clasa I minim-invazive la dinții permanenți tineri?","options":[{"id":"A","text":"Principiul exerezei totale a dentinei alterate."},{"id":"B","text":"Principiul utilizării materialelor adezive."},{"id":"C","text":"Principiul tratamentului plăgii dentinare."},{"id":"D","text":"Principiul economiei de țesut dentar."},{"id":"E","text":"Principiul extensiei preventive al lui Black."}],"correct":["E"],"pages":[409],"source":"set-2"},{"id":"set2-tUxZYJkQ","fingerprint":"e3a95c79208dab5a","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Care sunt afirmațiile corecte referitoare la enameloplastie (fisurotomie)?","options":[{"id":"A","text":"Este indicată pentru îndepărtarea completă a dentinei alterate."},{"id":"B","text":"Cavitatea rezultată este una ultraconservatoare, localizată la nivelul smalțului."},{"id":"C","text":"Are și o valoare de diagnostic pentru identificarea cariilor ajunse în dentină."},{"id":"D","text":"Se realizează exclusiv cu freze de mari dimensiuni pentru a asigura o vizibilitate optimă."},{"id":"E","text":"Este o metodă minim-invazivă prin care se îndepărtează strict smalțul afectat."}],"correct":["B","C","E"],"pages":[410],"source":"set-2"},{"id":"set2-LP5j07I1","fingerprint":"931ff951511ac475","chapterId":"set-2","subchapterId":"set2-5.04","type":"CS","text":"Ce caracteristică definește o cavitate clasa I conservatoare limitată în dentină?","options":[{"id":"A","text":"Are o lățime de 2-3 mm."},{"id":"B","text":"Unghiurile dentinare interne sunt lăsate ascuțite pentru a crește retenția."},{"id":"C","text":"Adâncimea sa depășește puțin joncțiunea smalț-dentină (JSD)."},{"id":"D","text":"Forma cavității este întotdeauna complexă, urmărind întregul sistem fisural."},{"id":"E","text":"Prezintă pereți laterali divergenți spre ocluzal."}],"correct":["C"],"pages":[410],"source":"set-2"},{"id":"set2-F6inuSwd","fingerprint":"a4f33b148c7981f4","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Care dintre următoarele situații reprezintă contraindicații pentru prepararea unei cavități clasa I conservatoare (atât limitată, cât și extinsă în dentină)?","options":[{"id":"A","text":"Carii ocluzale cu extindere mică în suprafață."},{"id":"B","text":"Carii ocluzale în zone cu încărcare ocluzală mare."},{"id":"C","text":"Carii ocluzale extinse care implică mai multe zone ale sistemului fisural ocluzal."},{"id":"D","text":"Pacienți cu risc mediu sau mare la carie."},{"id":"E","text":"Marmorații ocluzale suspecte de a ascunde carii în dentină."}],"correct":["B","C"],"pages":[410],"source":"set-2"},{"id":"set2-TMG7cH4E","fingerprint":"0cfc0d84858ff984","chapterId":"set-2","subchapterId":"set2-5.04","type":"CS","text":"Prin ce se diferențiază o cavitate clasa I conservatoare extinsă în dentină față de una limitată în dentină?","options":[{"id":"A","text":"Adâncimea este întotdeauna profundă."},{"id":"B","text":"Are o lățime mai mare, de 2-3 mm."},{"id":"C","text":"Prezintă pereți laterali divergenți spre ocluzal, spre deosebire de cea limitată."},{"id":"D","text":"Nu necesită rotunjirea unghiurilor dentinare interne."},{"id":"E","text":"Prepararea sa nu implică enameloplastie."}],"correct":["B"],"pages":[410],"source":"set-2"},{"id":"set2-fGIGqjyZ","fingerprint":"4f9cad7d0bab4a17","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Care dintre următoarele tipuri de cavități sunt considerate cavități proximale conservatoare de clasa a II-a minim-invazive?","options":[{"id":"A","text":"Cavitatea tip tunel."},{"id":"B","text":"Cavitatea tip șanț, fantă sau deget de mănușă."},{"id":"C","text":"Cavitatea ocluzală autoretentivă."},{"id":"D","text":"Cavitatea verticală redusă."},{"id":"E","text":"Cavitatea tip casetă."}],"correct":["A","B","D","E"],"pages":[410],"source":"set-2"},{"id":"set2-wMs9ACHI","fingerprint":"289d9d7663e4dd07","chapterId":"set-2","subchapterId":"set2-5.04","type":"CS","text":"Care este indicația specifică și abordarea pentru prepararea unei cavități verticale reduse?","options":[{"id":"A","text":"Carii proximale cu creasta marginală intactă, cu abordare tip tunel."},{"id":"B","text":"Marmorații ocluzale, cu abordare prin enameloplastie."},{"id":"C","text":"Carii ocluzale extinse, cu abordare directă ocluzală."},{"id":"D","text":"Carii proximale cu creasta subminată sau întreruptă limitat, cu abordare dinspre creasta marginală."},{"id":"E","text":"Carii proximale mici pe molarii temporari, cu abordare vestibulară."}],"correct":["D"],"pages":[410],"source":"set-2"},{"id":"set2-btc3n1rl","fingerprint":"fb700e04870698f1","chapterId":"set-2","subchapterId":"set2-5.04","type":"CS","text":"Care este o indicație specifică pentru prepararea unei cavități de tip casetă?","options":[{"id":"A","text":"O carie proximală cavitară mică, cu creasta marginală integră și dintele vecin absent."},{"id":"B","text":"O carie proximală cavitară mică, nedecelabilă clinic, dar vizibilă radiologic, cu dinte vecin prezent."},{"id":"C","text":"O carie proximală extinsă în dentină peste 0,5 mm, vizibilă clinic dinspre vestibular."},{"id":"D","text":"O carie proximală cu creasta marginală subminată sau întreruptă limitat."},{"id":"E","text":"O carie cavitară cu extindere mare în dentină, care necesită o abordare clasică."}],"correct":["A"],"pages":[411],"source":"set-2"},{"id":"set2-gEGUe8jk","fingerprint":"17fe5d23341b8b89","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Care dintre următoarele afirmații descriu corect prepararea unei cavități verticale reduse?","options":[{"id":"A","text":"Unghiul cavo-suprafață trebuie să aibă o valoare de 90°."},{"id":"B","text":"Pereții laterali sunt divergenți spre dintele vecin."},{"id":"C","text":"Șanțurile de retenție suplimentară se realizează la nivelul pragului gingival."},{"id":"D","text":"Pereții laterali sunt preparați convergenți spre ocluzal."},{"id":"E","text":"Pragul gingival se prepară la 0,5 mm deasupra punctului de contact."}],"correct":["A","B","D"],"pages":[411],"source":"set-2"},{"id":"set2-tykKSd-K","fingerprint":"1f4d41fb22b3b3ea","chapterId":"set-2","subchapterId":"set2-5.04","type":"CS","text":"Ce reprezintă o condiție esențială pentru prepararea unei cavități de tip tunel, șanț sau casetă?","options":[{"id":"A","text":"Extinderea procesului carios în dentină pe o adâncime de peste 0,5 mm, confirmată radiologic."},{"id":"B","text":"Posibilitatea de a vizualiza clinic leziunea dinspre vestibular sau oral."},{"id":"C","text":"Absența dintelui vecin pentru a permite un acces direct."},{"id":"D","text":"Prezența unei creste marginale integre și cu o grosime de cel puțin 2 mm."},{"id":"E","text":"Subminarea limitată a crestei marginale de către procesul carios."}],"correct":["D"],"pages":[411],"source":"set-2"},{"id":"set2-CgZLF5fs","fingerprint":"9abd9faf6a0a023d","chapterId":"set-2","subchapterId":"set2-5.04","type":"CS","text":"Cum se realizează accesul pentru o cavitate de tip tunel (clasa a II-a minim invazivă)?","options":[{"id":"A","text":"Prin îndepărtarea totală a smalțului subminat de pe suprafața ocluzală."},{"id":"B","text":"Direct dinspre proximal, cu o freză pară sau sferică la turbină."},{"id":"C","text":"Prin abordare de la nivelul crestei marginale, creând o cavitate verticală."},{"id":"D","text":"Direct dinspre vestibular sau oral, în funcție de proximitatea procesului carios."},{"id":"E","text":"Dinspre foseta ocluzală proximală, la 2 mm distanță de creasta marginală."}],"correct":["E"],"pages":[411],"source":"set-2"},{"id":"set2-oRBSxGCc","fingerprint":"e25787e8cb51705d","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"În care dintre următoarele etape se utilizează o freză sferică la turație convențională sau joasă?","options":[{"id":"A","text":"Exereza dentinei alterate (EDA) pentru o cavitate tip tunel."},{"id":"B","text":"Crearea accesului pentru o cavitate tip casetă."},{"id":"C","text":"Crearea accesului pentru o cavitate tip tunel."},{"id":"D","text":"Exereza dentinei alterate (EDA) pentru o cavitate tip casetă."},{"id":"E","text":"Realizarea șanțurilor de retenție pentru o cavitate verticală redusă."}],"correct":["A","D","E"],"pages":[411],"source":"set-2"},{"id":"set2-bmi5db3H","fingerprint":"02ac22b15deaf855","chapterId":"set-2","subchapterId":"set2-5.04","type":"CS","text":"Ce formă are o cavitate de tip șanț?","options":[{"id":"A","text":"O cavitate cu prag gingival concav și istm redus."},{"id":"B","text":"Formă rotundă sau ovalară, cu baza mai mare decât deschiderea."},{"id":"C","text":"Poate avea formă de deget de mănușă."},{"id":"D","text":"O cavitate care pornește dintr-o fosetă ocluzală și are o direcție oblică."},{"id":"E","text":"O cavitate verticală cu pereții convergenți spre ocluzal."}],"correct":["C"],"pages":[411],"source":"set-2"},{"id":"set2-Y21EsfiH","fingerprint":"a8b1ff930fb84e90","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Conform principiilor tehnicii clasice modificate, ce presupune etapa de creare a formei de contur extern?","options":[{"id":"A","text":"Limitarea preparării strict la zona proximală, menținând creasta marginală intactă."},{"id":"B","text":"Crearea unor pereți convergenți spre ocluzal pentru a asigura retenția."},{"id":"C","text":"Îndepărtarea totală a smalțului colorat și subminat."},{"id":"D","text":"Extinderea marginilor cavității în șanțurile și gropițele cu risc mare la carie."},{"id":"E","text":"Asigurarea condițiilor pentru parcurgerea etapelor de preparare și obturare."}],"correct":["C","D"],"pages":[411],"source":"set-2"},{"id":"set2-Y41pCdfx","fingerprint":"d84f226a997be1de","chapterId":"set-2","subchapterId":"set2-5.04","type":"CS","text":"În ce situație clinică este indicată exereza parțială a dentinei alterate în cadrul preparării unei cavități prin tehnica clasică modificată?","options":[{"id":"A","text":"În cazul cariilor simple foarte profunde, pentru a evita deschiderea camerei pulpare."},{"id":"B","text":"În toate cariile cu extindere în dentină, pentru a conserva structura dură dentară."},{"id":"C","text":"În cazul cariilor de clasa a V-a, pentru a îmbunătăți retenția materialului de obturație."},{"id":"D","text":"Atunci când smalțul adiacent este colorat și subminat."},{"id":"E","text":"În cazul cavităților de clasa a II-a, pentru a facilita extensia preventivă proximală."}],"correct":["A"],"pages":[412],"source":"set-2"},{"id":"set2-xeXcy6tx","fingerprint":"33c10b67947e7386","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Care sunt parametrii corecți ai extensiei preventive pentru o cavitate de clasa a II-a preparată prin tehnica clasică modificată?","options":[{"id":"A","text":"Îndepărtarea smalțului colorat marginal pentru a obține un efect estetic."},{"id":"B","text":"Crearea unui prag gingival la exact același nivel cu punctul de contact."},{"id":"C","text":"Înfundarea pragului gingival cu 0,5 mm sub punctul de contact."},{"id":"D","text":"Aducerea marginilor cavității pe pantele cuspidiene."},{"id":"E","text":"Extinderea pereților laterali verticali cu 0,5 mm în afara punctului de contact cu dintele vecin."}],"correct":["C","E"],"pages":[412],"source":"set-2"},{"id":"set2-6ShSk5k2","fingerprint":"e3824230cdda63ac","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Care dintre următoarele afirmații descriu corect principiile formei de rezistență în prepararea cavităților prin tehnica clasică modificată?","options":[{"id":"A","text":"Adâncimea minimă a preparației trebuie să fie de 0,5 mm în smalț."},{"id":"B","text":"La cavitățile de clasa I, pereții meziali și distali trebuie să fie convergenți spre ocluzal pentru a crește retenția."},{"id":"C","text":"Toate bolțile cuspidiene insuficient susținute de dentină la o cavitate de clasa a II-a trebuie îndepărtate."},{"id":"D","text":"La cavitățile de clasa a III-a și a IV-a, pereții laterali trebuie să aibă o grosime minimă de 0,5 mm pentru a rezista la gravajul acid."},{"id":"E","text":"Unghiul cavo-suprafață pentru cavitățile de clasa I și a II-a trebuie să fie de 90º."}],"correct":["D","E"],"pages":[412],"source":"set-2"},{"id":"set2-vbNNJTvH","fingerprint":"c0a5c472706723ff","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Ce caracteristici specifice are o cavitate de clasa I preparată prin tehnica clasică modificată?","options":[{"id":"A","text":"Pereții laterali vestibulari și orali sunt ușor convergenți spre ocluzal."},{"id":"B","text":"Adâncimea minimă a preparației este de 0,5 mm de la suprafața ocluzală a smalțului."},{"id":"C","text":"Pereții meziali și distali sunt paraleli."},{"id":"D","text":"Unghiurile interne sunt ascuțite pentru a maximiza retenția."},{"id":"E","text":"Unghiul cavo-suprafață este de 90º."}],"correct":["A","C","E"],"pages":[412],"source":"set-2"},{"id":"set2-0iv1O1gu","fingerprint":"7210908dcf6ff095","chapterId":"set-2","subchapterId":"set2-5.04","type":"CS","text":"Cum sunt gestionate șanțurile și fisurile marginale restante și retentive în cazul preparării unei cavități de clasa I clasică modificată la un pacient cu risc mare la carie?","options":[{"id":"A","text":"Se înglobează în conturul extern al cavității."},{"id":"B","text":"Se lasă neatinse, deoarece preparația se oprește în dentină."},{"id":"C","text":"Se bizotează pentru o mai bună adaptare a materialului de obturație."},{"id":"D","text":"Se sigilează, limitând astfel extensia preventivă."},{"id":"E","text":"Se creează cavități suplimentare de retenție în aceste zone."}],"correct":["A"],"pages":[412],"source":"set-2"},{"id":"set2-IFhdf5UK","fingerprint":"1b5124857757e962","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Ce presupune etapa de finisare în cadrul preparării unei cavități prin tehnica clasică modificată?","options":[{"id":"A","text":"Bizotarea marginilor neregulate de smalț la cavitățile de clasa I și a II-a."},{"id":"B","text":"Netezirea marginilor anfractuoase de smalț."},{"id":"C","text":"Stabilirea adâncimii minime de 0,5 mm în dentină."},{"id":"D","text":"Rotunjirea unghiurilor externe ale cavității."},{"id":"E","text":"Crearea unor cavități suplimentare de retenție, cum ar fi coada de rândunică."}],"correct":["A","B","D"],"pages":[412],"source":"set-2"},{"id":"set2-_h6Iv7X8","fingerprint":"f42d13e580cf7cc1","chapterId":"set-2","subchapterId":"set2-5.04","type":"CS","text":"Care este o indicație corectă pentru prepararea unei cavități de clasa a II-a prin tehnica clasică modificată?","options":[{"id":"A","text":"O carie ocluzală cu extindere laterală mare în dentină de-a lungul joncțiunii smalț-dentină."},{"id":"B","text":"Orice cavitate care intră în contact extins cu dintele antagonist."},{"id":"C","text":"O carie localizată exclusiv în șanțuri și fosete, fără afectare proximală."},{"id":"D","text":"O carie proximală de mici dimensiuni cu creasta marginală intactă."},{"id":"E","text":"O carie proximală mare cu creastă marginală subminată pe un dinte permanent lateral."}],"correct":["E"],"pages":[412],"source":"set-2"},{"id":"set2-TIrWchDN","fingerprint":"81afd5c42341cb66","chapterId":"set-2","subchapterId":"set2-5.04","type":"CS","text":"Care dintre următoarele caracteristici corespunde cavității orizontale în prepararea unei cavități de clasa a II-a clasică modificată?","options":[{"id":"A","text":"Adâncimea este de 1,5 mm sub joncțiunea smalț-dentină (JSD)."},{"id":"B","text":"Grosimea minimă a marginilor cavității este de 0,5 mm."},{"id":"C","text":"Poate prezenta o formă de 'S' sau 'S' inversat."},{"id":"D","text":"Unghiurile interne sunt ascuțite pentru a crește rezistența."},{"id":"E","text":"Pereții laterali sunt divergenți spre ocluzal."}],"correct":["C"],"pages":[413],"source":"set-2"},{"id":"set2-6Z-I_RV_","fingerprint":"5af15c475792f0fb","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Selectați afirmațiile corecte referitoare la prepararea unei cavități de clasa a II-a clasică modificată.","options":[{"id":"A","text":"Pragul gingival se înfundă 0,5 mm sub punctul de contact."},{"id":"B","text":"Extensia preventivă constă în îndepărtarea smalțului colorat marginal."},{"id":"C","text":"Este indicată pentru carii proximale incipiente cu creastă marginală intactă."},{"id":"D","text":"Unghiul cavo-suprafață trebuie să fie de 45 de grade."},{"id":"E","text":"Lățimea istmului este de 1/4 până la 1/3 din lățimea bicuspidiană vestibulo-orală."}],"correct":["A","E"],"pages":[413],"source":"set-2"},{"id":"set2-iA20skVb","fingerprint":"d0592fb72bae3ad7","chapterId":"set-2","subchapterId":"set2-5.04","type":"CS","text":"Care sunt caracteristicile comune ale preparărilor pentru cavitățile de clasa a III-a și clasa a V-a clasice modificate?","options":[{"id":"A","text":"Adâncimea preparării este standardizată la 0,5 mm sub JSD."},{"id":"B","text":"Coroziunea materialului din care este confecționat știftul."},{"id":"C","text":"Retenția este asigurată prin pereți laterali convergenți spre exterior."},{"id":"D","text":"Finisarea implică bizotarea marginilor de smalț."},{"id":"E","text":"Conturul extern are o formă exclusiv reniformă."}],"correct":["C"],"pages":[413],"source":"set-2"},{"id":"set2-1fIyL1ur","fingerprint":"9c958eb9e6ace9f6","chapterId":"set-2","subchapterId":"set2-5.04","type":"CS","text":"Care este principalul risc asociat cu aplicarea știfturilor parapulpare pentru retenție în cavitățile de clasa a IV-a la dinții permanenți tineri?","options":[{"id":"A","text":"Fracturarea știftului în timpul inserării."},{"id":"B","text":"Carii de colet."},{"id":"C","text":"Interferența cu procesul de maturare a rădăcinii."},{"id":"D","text":"Insuficiența retenției datorită dentinei slab mineralizate."},{"id":"E","text":"Deschiderea camerei pulpare."}],"correct":["E"],"pages":[413],"source":"set-2"},{"id":"set2-fboIHFAI","fingerprint":"affcc6139e7a7ee7","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Care este indicația corectă pentru o cavitate de clasa a VI-a clasică modificată?","options":[{"id":"A","text":"Carii pe vârful cuspizilor."},{"id":"B","text":"Carii proximale pe dinții frontali cu păstrarea integrității unghiului incizal."},{"id":"C","text":"Carii proximale mari pe dinții permanenți laterali."},{"id":"D","text":"Carii proximale pe dinții frontali fără păstrarea integrității unghiului incizal."},{"id":"E","text":"Carii pe marginea incizală."}],"correct":["A","E"],"pages":[413],"source":"set-2"},{"id":"set2-lgxDzH_R","fingerprint":"7ba231b242d5c2f2","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Care sunt principiile și indicațiile tehnicii restaurative atraumatice (ART)?","options":[{"id":"A","text":"Necesită extensie preventivă pentru a îndepărta șanțurile și fosetele adiacente."},{"id":"B","text":"Prepararea cavității se realizează cu instrumentar manual, precum dalta de smalț și excavatorul."},{"id":"C","text":"Este indicată pentru carii cavitare cu extindere mare în dentină la copii și adolescenți necooperanți."},{"id":"D","text":"Se aplică doar în cavități superficiale care nu depășesc joncțiunea smalț-dentină."},{"id":"E","text":"Obturarea cavității se efectuează cu ciment ionomer de sticlă (CIS)."}],"correct":["B","C","E"],"pages":[414],"source":"set-2"},{"id":"set2-3xql8EzU","fingerprint":"5f898d10f00b45cd","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Care dintre următoarele reprezintă obiective ale tratamentului plăgii dentinare (TPD)?","options":[{"id":"A","text":"Protecția biologică a pulpei față de invazia bacteriană și toxinele acestora."},{"id":"B","text":"Îndepărtarea completă a dentinei sănătoase pentru a asigura retenția obturației."},{"id":"C","text":"Expunerea deliberată a coarnelor pulpare pentru a facilita vindecarea."},{"id":"D","text":"Sigilarea canaliculelor dentinare expuse prin prepararea cavității."},{"id":"E","text":"Stimularea formării de dentină nouă (neodentinogeneza)."}],"correct":["A","D","E"],"pages":[414],"source":"set-2"},{"id":"set2-DBXI8kA0","fingerprint":"56d3bd54925d0197","chapterId":"set-2","subchapterId":"set2-5.04","type":"CS","text":"Ce metodă de tratament a plăgii dentinare se aplică în cariile profunde unde peretele pulpar este întrerupt de o deschidere punctiformă a camerei pulpare?","options":[{"id":"A","text":"Tehnica excavațiilor succesive (step-wise technique)"},{"id":"B","text":"Aplicarea unei obturații de bază din FOZ"},{"id":"C","text":"Coafajul indirect"},{"id":"D","text":"Coafajul direct"},{"id":"E","text":"Coafajul natural"}],"correct":["D"],"pages":[414],"source":"set-2"},{"id":"set2-FzelS71o","fingerprint":"6e07a11552d3f519","chapterId":"set-2","subchapterId":"set2-5.04","type":"CS","text":"Ce procedură este recomandată pentru tratamentul unei cavități superficiale?","options":[{"id":"A","text":"Toaleta cavității cu H₂O₂, urmată de o obturație de bază din CIS sau FOZ."},{"id":"B","text":"Toaleta cavității cu alcool și H₂O₂, urmată de aplicarea unui liner CIS fotopolimerizabil, Ca(OH)₂ sau bonding."},{"id":"C","text":"Toaleta cavității cu ser fiziologic sau apă distilată și aplicarea unui coafaj indirect."},{"id":"D","text":"Realizarea unui coafaj direct cu MTA și o obturație de bază din FOZ."},{"id":"E","text":"Aplicarea directă a unei obturații preventive cu rășină tipul 2 (OPR2)."}],"correct":["B"],"pages":[414],"source":"set-2"},{"id":"set2-p8yKgwok","fingerprint":"566e958ab263955c","chapterId":"set-2","subchapterId":"set2-5.04","type":"CS","text":"Care este definiția coafajului natural?","options":[{"id":"A","text":"O metodă ce implică obturarea cavității cu compozit flow și sigilarea șanțurilor și fosetelor adiacente."},{"id":"B","text":"O procedură de tratament pentru cavități medii ce folosește o bază de ciment ionomer de sticlă."},{"id":"C","text":"O metodă aplicată în carii profunde unde peretele pulpar este alcătuit din dentină sănătoasă, dar este întrerupt de o cantitate mică de dentină alterată care, dacă ar fi îndepărtată, ar deschide camera pulpară."},{"id":"D","text":"O metodă aplicată în carii profunde unde peretele dentinar profund este intact, format integral din dentină dură sănătoasă."},{"id":"E","text":"O metodă aplicată în carii profunde unde există deja o deschidere punctiformă a camerei pulpare."}],"correct":["C"],"pages":[414],"source":"set-2"},{"id":"set2-1BS_qRMa","fingerprint":"9d658a32ad41581b","chapterId":"set-2","subchapterId":"set2-5.04","type":"CS","text":"Ce caracterizează obturația preventivă cu rășină tipul 1 (OPR1) într-o cavitate clasa I ultraconservatoare?","options":[{"id":"A","text":"Este o tehnică ce necesită menținerea unei obturații temporare timp de 6-8 săptămâni."},{"id":"B","text":"Se aplică un liner de ciment ionomer de sticlă (CIS) înainte de obturația finală."},{"id":"C","text":"Cavitatea este obturată cu compozit flow, iar ulterior se sigilează atât obturația, cât și șanțurile și fosetele nepreparate."},{"id":"D","text":"Este indicată pentru cavități care depășesc joncțiunea smalț-dentină cu mai mult de 0,5 mm."},{"id":"E","text":"Se utilizează exclusiv un material de sigilare pentru a umple cavitatea preparată."}],"correct":["C"],"pages":[414],"source":"set-2"},{"id":"set2-t35nNx24","fingerprint":"fd454f3b2230ac38","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Conform descrierii, ce particularități are coafajul natural?","options":[{"id":"A","text":"Se menține pentru o perioadă de minimum 6-8 săptămâni."},{"id":"B","text":"Derivă din coafajul indirect."},{"id":"C","text":"Poate fi repetat de mai multe ori, constituind tehnica excavațiilor succesive."},{"id":"D","text":"Materialul de elecție este întotdeauna cimentul ionomer de sticlă."},{"id":"E","text":"Este indicat pentru cavități superficiale, limitate la 0,5 mm în dentină."}],"correct":["A","B","C"],"pages":[414],"source":"set-2"},{"id":"set2-Q80_13p8","fingerprint":"58b256dde5406afc","chapterId":"set-2","subchapterId":"set2-5.04","type":"CS","text":"Ce caracteristici definesc o cavitate clasa I conservatoare pentru care este indicată o obturație preventivă cu rășină tip 2 (OPR2)?","options":[{"id":"A","text":"Cavitatea este profundă și necesită coafaj indirect cu hidroxid de calciu."},{"id":"B","text":"Preparația are o extindere laterală mare în dentină și intră limitat în contact cu dintele antagonist."},{"id":"C","text":"Cavitatea este superficială, extinzându-se 0,5 mm în dentină și nu are contact cu antagonistul."},{"id":"D","text":"Cavitatea este de tip șanț și se obturează cu CIS condensabil."},{"id":"E","text":"Cavitatea este de adâncime medie și necesită o bază de ciment ionomer de sticlă (CIS)."}],"correct":["C"],"pages":[415],"source":"set-2"},{"id":"set2-BlNjeIJg","fingerprint":"374b655ac7f6f151","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Care dintre următoarele afirmații descriu corect particularitățile pulpei unui dinte permanent imatur?","options":[{"id":"A","text":"Substanța fundamentală are un grad mare de hidratare, ceea ce asigură menținerea constantă a presiunii intrapulpare."},{"id":"B","text":"Zona subodontoblastică Weil este slab vascularizată."},{"id":"C","text":"Conține numeroase celule nediferențiate de tip tânăr cu capacitate mare de transformare."},{"id":"D","text":"Prezintă un prag dureros crescut la testarea electrometrică datorită imaturității integrării fibrelor nervoase cu prelungirile odontoblastelor."},{"id":"E","text":"Este bogată în fibre de colagen, ceea ce îi conferă o rezistență structurală ridicată."}],"correct":["A","C","D"],"pages":[415],"source":"set-2"},{"id":"set2-W5IVqFKz","fingerprint":"c72ca3209b86eedc","chapterId":"set-2","subchapterId":"set2-5.04","type":"CS","text":"Care este atitudinea terapeutică recomandată pentru o cavitate clasa a II-a MI tip tunel?","options":[{"id":"A","text":"TPD urmat de obturație cu compozit, compomer sau CIS și derivații săi."},{"id":"B","text":"Coafaj indirect urmat de obturație de bază cu CIS și obturație finală."},{"id":"C","text":"TPD urmat de obturație cu ciment ionomer de sticlă condensabil."},{"id":"D","text":"TPD urmat de obturație din compozit sau compomer."},{"id":"E","text":"TPD urmat de o obturație laminată cu ciment ionomer de sticlă și compozit."}],"correct":["E"],"pages":[415],"source":"set-2"},{"id":"set2-GcoLhYuA","fingerprint":"b5b1ac01ce61e11f","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Care sunt particularitățile morfo-structurale ale dinților permanenți imaturi?","options":[{"id":"A","text":"Canalele radiculare sunt mai largi în sens mezio-distal decât în sens vestibulo-oral."},{"id":"B","text":"Țesutul conjunctiv periapical devine inactiv în absența pulpei vii."},{"id":"C","text":"Pereții radiculari meziali și distali se dezvoltă mai repede decât cei vestibulari și orali."},{"id":"D","text":"Prezintă o cameră pulpară mare și un apex deschis, de formă ovalară."},{"id":"E","text":"Pereții radiculari sunt groși și convergenți de la începutul dezvoltării."}],"correct":["C","D"],"pages":[415],"source":"set-2"},{"id":"set2-sYc83gJE","fingerprint":"8d89dfdf5ac30377","chapterId":"set-2","subchapterId":"set2-5.04","type":"CS","text":"Care este secvența corectă a manoperelor și materialelor pentru o obturație preventivă cu rășină tip 3 (OPR 3) într-o cavitate profundă de clasa I?","options":[{"id":"A","text":"Aplicarea unui liner de CIS/varnish/bonding, urmată de obturație cu compozit și sigilare."},{"id":"B","text":"TPD urmat de o obturație laminată: CIS plus compozit."},{"id":"C","text":"Coafaj indirect cu Ca(OH)₂, obturație de bază cu CIS, obturație cu compozit/compomer și sigilare."},{"id":"D","text":"Obturație cu CIS condensabil și sigilarea ulterioară a șanțurilor."},{"id":"E","text":"Obturație de bază cu CIS, urmată de obturație cu compozit și sigilarea șanțurilor."}],"correct":["C"],"pages":[415],"source":"set-2"},{"id":"set2-YcYsXxVx","fingerprint":"165d0a34b3a71ba4","chapterId":"set-2","subchapterId":"set2-5.04","type":"CS","text":"Conform clasificării formelor clinice de carie complicată, care dintre următoarele afecțiuni este considerată o pulpita ireversibilă?","options":[{"id":"A","text":"Toate formele de pulpită acută seroasă parțială."},{"id":"B","text":"Pulpita acută seroasă parțială în stadiul 1."},{"id":"C","text":"Orice inflamație pulpară la un dinte permanent imatur."},{"id":"D","text":"Hiperemia pulpară."},{"id":"E","text":"Pulpita acută seroasă parțială în stadiul 2 de evoluție."}],"correct":["E"],"pages":[415],"source":"set-2"},{"id":"set2-r6I6deKW","fingerprint":"944880278449743f","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Care dintre următoarele afecțiuni sunt clasificate ca pulpite ireversibile?","options":[{"id":"A","text":"Hiperemia pulpară"},{"id":"B","text":"Pulpita acută seroasă parțială în stadiul 2 de evoluție"},{"id":"C","text":"Pulpita acută seroasă parțială în stadiul 1"},{"id":"D","text":"Pulpitele purulente"},{"id":"E","text":"Pulpitele cronice"}],"correct":["B","D","E"],"pages":[416],"source":"set-2"},{"id":"set2-Xr6o_i_L","fingerprint":"dd2ea5f35b409ff5","chapterId":"set-2","subchapterId":"set2-5.04","type":"CS","text":"Ce afecțiune este considerată o formă de pulpită reversibilă?","options":[{"id":"A","text":"Necroza pulpară"},{"id":"B","text":"Pulpita purulentă"},{"id":"C","text":"Pulpita seroasă totală"},{"id":"D","text":"Gangrena pulpară simplă"},{"id":"E","text":"Hiperemia pulpară"}],"correct":["E"],"pages":[416],"source":"set-2"},{"id":"set2-L95rZNW1","fingerprint":"4e2c4de888b844bf","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Care dintre următorii factori sunt menționați în etiologia cariei complicate?","options":[{"id":"A","text":"Forțele ortodontice"},{"id":"B","text":"Eroziunea acidă"},{"id":"C","text":"Traumatismele"},{"id":"D","text":"Boala parodontală"},{"id":"E","text":"Abraziunea dentară"}],"correct":["A","C","D"],"pages":[416],"source":"set-2"},{"id":"set2-pyeds7Lp","fingerprint":"0a88111171ef8e17","chapterId":"set-2","subchapterId":"set2-5.04","type":"CS","text":"În cazul pulpitei acute seroase în faza de debut, cât timp poate persista durerea după îndepărtarea stimulului?","options":[{"id":"A","text":"Durerea încetează imediat"},{"id":"B","text":"1-2 minute"},{"id":"C","text":"Până la 10-15 minute"},{"id":"D","text":"Durerea este continuă și nu cedează"},{"id":"E","text":"Peste 30 de minute"}],"correct":["C"],"pages":[416],"source":"set-2"},{"id":"set2-cFgtXDwv","fingerprint":"e0155ccd01c93e62","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Care sunt caracteristicile durerii în pulpitele reversibile, conform examenului subiectiv?","options":[{"id":"A","text":"Cedează spontan"},{"id":"B","text":"Este provocată de agenți fizici (rece) și chimici (dulce)"},{"id":"C","text":"Are caracter lancinant"},{"id":"D","text":"Este constantă și iradiază la dinții vecini"},{"id":"E","text":"Este exacerbată de căldură"}],"correct":["A","B","C"],"pages":[416],"source":"set-2"},{"id":"set2-eJ1Dajow","fingerprint":"4d9f111481e9b608","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Ce relevă, de obicei, palparea cu sonda în cazul unei pulpite reversibile?","options":[{"id":"A","text":"Dentină alterată, de obicei moale"},{"id":"B","text":"Camera pulpară integră"},{"id":"C","text":"Deschiderea camerei pulpare"},{"id":"D","text":"Absența sensibilității pe pereții laterali"},{"id":"E","text":"O podea a camerei pulpare dură și rezistentă"}],"correct":["A","B"],"pages":[416],"source":"set-2"},{"id":"set2-SFuMSZ4s","fingerprint":"0cb94993c50c8a90","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Ce informație este specifică utilizării testelor de vitalitate termice la copii pentru diagnosticarea pulpitelor reversibile?","options":[{"id":"A","text":"Sunt metoda de diagnostic de elecție"},{"id":"B","text":"Indică un prag al excitabilității pulpare scăzut"},{"id":"C","text":"Oferă informații incerte și eronate"},{"id":"D","text":"Confirmă întotdeauna diagnosticul de hiperemie"},{"id":"E","text":"Se folosesc rar"}],"correct":["C","E"],"pages":[416],"source":"set-2"},{"id":"set2-H6Mpoi6V","fingerprint":"58623b3ac857b943","chapterId":"set-2","subchapterId":"set2-5.04","type":"CS","text":"Care este atitudinea terapeutică indicată în pulpitele reversibile conform informațiilor prezentate?","options":[{"id":"A","text":"Monitorizarea fără intervenție"},{"id":"B","text":"Aplicarea unui pansament calmant"},{"id":"C","text":"Extracția dintelui afectat"},{"id":"D","text":"Extirparea vitală a pulpei dentare"},{"id":"E","text":"Conservarea în totalitate a pulpei prin coafaje"}],"correct":["E"],"pages":[416],"source":"set-2"},{"id":"set2-eRVIME-n","fingerprint":"c627dcec272656e7","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Ce poate releva inspecția în cadrul examenului obiectiv pentru o pulpită reversibilă?","options":[{"id":"A","text":"O fistulă la nivelul gingiei"},{"id":"B","text":"Modificări de culoare ale dintelui (alb-cretos, brun)"},{"id":"C","text":"Integritatea smalțului pe toate suprafețele"},{"id":"D","text":"Papile gingivale tumefiate și congestive"},{"id":"E","text":"Mobilitate dentară crescută"}],"correct":["B","D"],"pages":[416],"source":"set-2"},{"id":"set2-pw4rLRC3","fingerprint":"bf08d09cdd4d10db","chapterId":"set-2","subchapterId":"set2-5.04","type":"CS","text":"Care este răspunsul caracteristic al durerii la stimuli termici în cazul pulpitei acute seroase totale?","options":[{"id":"A","text":"Durerea este exacerbată de rece și parțial calmată la cald."},{"id":"B","text":"Durerea este calmată complet atât la rece, cât și la cald."},{"id":"C","text":"Durerea este provocată exclusiv de dulce, fără a fi afectată de stimuli termici."},{"id":"D","text":"Durerea este constantă și nu este influențată de variațiile de temperatură."},{"id":"E","text":"Durerea este provocată de cald și parțial calmată la rece."}],"correct":["A"],"pages":[417],"source":"set-2"},{"id":"set2-uKNeYrnu","fingerprint":"13b9f05b138b7204","chapterId":"set-2","subchapterId":"set2-5.04","type":"CS","text":"Ce caracteristici clinice sunt specifice pulpitei purulente parțiale?","options":[{"id":"A","text":"Percuția în ax este pozitivă."},{"id":"B","text":"Durerea are un caracter pulsatil, sincron cu pulsul."},{"id":"C","text":"Palparea cu sonda a camerei pulpare provoacă o sângerare în cantitate mică, roșu-deschis, fără prezența puroiului."},{"id":"D","text":"Testele de vitalitate indică hiperexcitabilitate."},{"id":"E","text":"Durerile sunt calmate de cald și exacerbate de rece."}],"correct":["B"],"pages":[417],"source":"set-2"},{"id":"set2-ej_jtV0c","fingerprint":"9af7630e190207c6","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Care dintre următoarele afirmații descriu corect caracteristicile comune durerii în pulpitele purulente (parțială și totală)?","options":[{"id":"A","text":"Durerea este exacerbată la creșterea fluxului sanguin în extremitatea cefalică."},{"id":"B","text":"Durerile sunt iradiate în hemicraniu."},{"id":"C","text":"Durerea are un caracter pulsatil."},{"id":"D","text":"Durerea este exacerbată la cald."},{"id":"E","text":"Durerile cedează complet la antialgicele obișnuite."}],"correct":["A","C","D"],"pages":[417],"source":"set-2"},{"id":"set2-JhJMmT7Z","fingerprint":"1c56c05f99370d14","chapterId":"set-2","subchapterId":"set2-5.04","type":"CS","text":"Ce relevă examenele complementare și manevrele terapeutice în cazul unei pulpite acute seroase totale?","options":[{"id":"A","text":"Testele de vitalitate trebuie evitate deoarece pot genera un comportament negativ al copilului."},{"id":"B","text":"Radiografia este neconcludentă și nu poate arăta deschiderea camerei pulpare."},{"id":"C","text":"Percuția în ax este negativă."},{"id":"D","text":"Aplicarea unui pansament calmant cu anestezic este contraindicată."},{"id":"E","text":"Forajul explorator este manevra de elecție pentru calmarea imediată a durerii."}],"correct":["A"],"pages":[417],"source":"set-2"},{"id":"set2-rVGfmMZi","fingerprint":"339d7e667f9fbf1e","chapterId":"set-2","subchapterId":"set2-5.04","type":"CS","text":"În timpul examenului obiectiv al unei pulpite purulente parțiale, care este secvența de evenimente la palparea cu sonda a camerei pulpare deschise?","options":[{"id":"A","text":"Apariția unei sângerări roșii, urmată de eliminarea puroiului și calmarea durerii."},{"id":"B","text":"Eliminarea puroiului, exacerbarea durerii, scăderea durerii, apariția sângerării."},{"id":"C","text":"Hipoexcitabilitate, fără durere sau sângerare la palpare."},{"id":"D","text":"Calmarea imediată a durerii, urmată de o sângerare roșie."},{"id":"E","text":"O durere puternică la atingere și o sângerare roșu-deschis, în cantitate mică."}],"correct":["B"],"pages":[417],"source":"set-2"},{"id":"set2-0hZMDpSG","fingerprint":"ebe29942c06bce71","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Care sunt manifestările clinice și paraclinice caracteristice pulpitei purulente totale?","options":[{"id":"A","text":"Testele de vitalitate indică hiperexcitabilitate pulpară."},{"id":"B","text":"Percuția în axul dintelui este pozitivă."},{"id":"C","text":"Durerea este exacerbată la cald și calmată temporar la rece."},{"id":"D","text":"Dureri spontane, intense, cu caracter pulsatil, iradiate în hemicraniu."},{"id":"E","text":"Calmarea imediată și completă a durerii la eliminarea puroiului prin decompresie."}],"correct":["B","C","D"],"pages":[417,418],"source":"set-2"},{"id":"set2-iXCDhx8S","fingerprint":"0193a5bcaa0419fc","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Ce elemente se regăsesc în tabloul clinic al pulpitelor ireversibile cronice?","options":[{"id":"A","text":"Palparea pulpei inflamate cronic provoacă sângerare abundentă de culoare roșu închis."},{"id":"B","text":"Percuția în ax este negativă."},{"id":"C","text":"Testele de vitalitate sunt negative."},{"id":"D","text":"Durerile pot fi surde, provocate de masticație, sau uneori pot lipsi."},{"id":"E","text":"Camera pulpară este întotdeauna închisă, protejată de obturații vechi."}],"correct":["A","B","D"],"pages":[418],"source":"set-2"},{"id":"set2-A7Qytg8A","fingerprint":"9cd7be6148d5aa62","chapterId":"set-2","subchapterId":"set2-5.04","type":"CS","text":"Care este secvența corectă a evenimentelor la palparea cu sonda a unei pulpite purulente totale cu camera pulpară deschisă?","options":[{"id":"A","text":"Lipsa sângerării și a sensibilității, cu prezența unui țesut pulpar de culoare gri."},{"id":"B","text":"Sensibilitate redusă și sângerare roșu închis abundentă la atingerea pulpei."},{"id":"C","text":"Eliminarea puroiului, exacerbarea durerii, scăderea durerii după 20-30 de minute, apariția unei sângerări roșu închis."},{"id":"D","text":"Sângerare abundentă, greu de controlat, urmată de eliminarea puroiului."},{"id":"E","text":"Eliminarea puroiului, calmarea imediată a durerii, sângerare roșu aprins."}],"correct":["C"],"pages":[418],"source":"set-2"},{"id":"set2-F_GVBj5K","fingerprint":"5ceadabca20df8c4","chapterId":"set-2","subchapterId":"set2-5.04","type":"CS","text":"Ce constatare la deschiderea camerei pulpare este specifică necrozei pulpare?","options":[{"id":"A","text":"Se relevă o sensibilitate redusă și o sângerare abundentă, roșu închis."},{"id":"B","text":"Se observă un polip pulpar care umple cavitatea carioasă."},{"id":"C","text":"Se elimină puroi și sânge de stază, calmând durerea în timp."},{"id":"D","text":"Pulpa sângerează roșu închis la cea mai mică atingere, iar sângerarea este greu de controlat."},{"id":"E","text":"Pulpa are o culoare gri, fără sângerare și fără sensibilitate."}],"correct":["E"],"pages":[418],"source":"set-2"},{"id":"set2-FXoPj5MF","fingerprint":"d5d3c85ce732a854","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Care dintre următoarele afecțiuni pulpare prezintă un răspuns negativ la percuția în ax?","options":[{"id":"A","text":"Pulpita purulentă parțială."},{"id":"B","text":"Pulpita purulentă totală."},{"id":"C","text":"Necroza pulpară."},{"id":"D","text":"Pulpita cronică închisă."},{"id":"E","text":"Pulpita ireversibilă cronică."}],"correct":["A","C","D","E"],"pages":[418],"source":"set-2"},{"id":"set2-mV5bJ3No","fingerprint":"7deaad618a68c083","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Prin ce se diferențiază o pulpită cronică deschisă de una închisă, conform examenului obiectiv și paraclinic?","options":[{"id":"A","text":"Pulpita cronică închisă se asociază cu dureri surde sub obturații, iar cea deschisă cu dureri la masticație."},{"id":"B","text":"Pulpita cronică deschisă prezintă polipi pulpari sau ulcerații, spre deosebire de cea închisă."},{"id":"C","text":"La inspecție, pulpita cronică închisă prezintă carii profunde cu dentină dură colorată sau obturații mari, vechi, spre deosebire de cea deschisă, care prezintă obturații voluminoase, polipi pulpari care umplu cavitatea carioasă."},{"id":"D","text":"Testele de vitalitate sunt slab pozitive în forma deschisă și negative în forma închisă."},{"id":"E","text":"În pulpita cronică deschisă, camera pulpară este deschisă, cu durere redusă la suprafața pulpei, în timp ce în cea închisă, este închisă."}],"correct":["B","C","E"],"pages":[418],"source":"set-2"},{"id":"set2-Q4b0hx6g","fingerprint":"af3a5cd947f7093a","chapterId":"set-2","subchapterId":"set2-5.04","type":"CS","text":"Un pacient prezintă o cavitate profundă cu dentină ramolită. La palparea cu sonda, camera pulpară este deschisă, pulpa este de culoare gri, consistență moale, fetidă, și nu prezintă sensibilitate sau sângerare. Percuția în ax este negativă. Care este cel mai probabil diagnostic?","options":[{"id":"A","text":"Parodontită apicală cronică"},{"id":"B","text":"Parodontită apicală acută în stadiu endoosos"},{"id":"C","text":"Gangrenă pulpară simplă"},{"id":"D","text":"Parodontită apicală acută în stadiu exteriorizat"},{"id":"E","text":"Parodontită apicală cronică acutizată"}],"correct":["C"],"pages":[419],"source":"set-2"},{"id":"set2-CESApSSr","fingerprint":"d3043c5d56d15fbe","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Care dintre următoarele caracteristici ale pulpei sunt întâlnite atât în gangrena pulpară simplă, cât și în cea complicată cu parodontită apicală (acută sau cronică)?","options":[{"id":"A","text":"Culoare gri"},{"id":"B","text":"Miros fetid"},{"id":"C","text":"Consistență moale"},{"id":"D","text":"Sensibilitate la palparea cu sonda"},{"id":"E","text":"Sângerare la palparea cu sonda"}],"correct":["A","B","C"],"pages":[419],"source":"set-2"},{"id":"set2-HtFeL-Tb","fingerprint":"de061ea30e66659a","chapterId":"set-2","subchapterId":"set2-5.04","type":"CS","text":"Un pacient acuză dureri de intensitate mare, spontane, iradiate și o senzație de egresiune a dintelui. Examenul clinic relevă mobilitate crescută și o reacție dureroasă intensă la percuția în ax. Care este diagnosticul corespunzător acestui tablou clinic?","options":[{"id":"A","text":"Gangrenă pulpară simplă"},{"id":"B","text":"Parodontită apicală acută în stadiu endoosos"},{"id":"C","text":"Parodontită apicală cronică"},{"id":"D","text":"Parodontită apicală acută în stadiu exteriorizat (abces)"},{"id":"E","text":"Parodontită apicală cronică acutizată"}],"correct":["B"],"pages":[419],"source":"set-2"},{"id":"set2-IznsMK8z","fingerprint":"89bd2a1a390df5ad","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Care sunt afirmațiile corecte referitoare la parodontita apicală cronică?","options":[{"id":"A","text":"Pulpa prezintă sensibilitate la palparea cu sonda."},{"id":"B","text":"Percuția în ax este, de regulă, negativă sau provoacă o jenă ușoară."},{"id":"C","text":"Durerea are o intensitate redusă, dar se poate exacerba."},{"id":"D","text":"Testele de vitalitate sunt negative, dar nu se efectuează în perioadele de acutizare."},{"id":"E","text":"Examenul radiologic poate releva o zonă de osteită periapicală."}],"correct":["B","C","D","E"],"pages":[419],"source":"set-2"},{"id":"set2-Nl1zZNdf","fingerprint":"13d4ec6f97e3769e","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Care dintre următoarele reprezintă metode de tratament pulpar recomandate la dinții permanenți imaturi (DPI)?","options":[{"id":"A","text":"Revascularizarea"},{"id":"B","text":"Pulpectomia non-vitală"},{"id":"C","text":"Coafajul direct"},{"id":"D","text":"Apexogeneza"},{"id":"E","text":"Pulpotomia parțială vitală"}],"correct":["A","B","C","E"],"pages":[420],"source":"set-2"},{"id":"set2-c_0Xo1G5","fingerprint":"4184fe70493f8d4b","chapterId":"set-2","subchapterId":"set2-5.04","type":"CS","text":"Ce definește apexogeneza?","options":[{"id":"A","text":"O procedură terapeutică de creare a unei bariere apicale în cazul necrozei pulpare totale."},{"id":"B","text":"Extirparea parțială a pulpei vii urmată de aplicarea unei medicații specifice."},{"id":"C","text":"Procesul fiziologic de creștere a rădăcinii și de închidere a apexului, bazat pe pulpa vie restantă și stimulată terapeutic."},{"id":"D","text":"Metoda de tratament a plăgii dentinare în care se păstrează în totalitate pulpa vie."},{"id":"E","text":"Amputația totală a pulpei coronare vii."}],"correct":["C"],"pages":[420],"source":"set-2"},{"id":"set2-UtQFXKuS","fingerprint":"2494fe61c873d0ed","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Care dintre următoarele tratamente sunt menționate ca stimulând apexogeneza?","options":[{"id":"A","text":"Pulpotomia vitală parțială sau totală"},{"id":"B","text":"Coafajele pulpare"},{"id":"C","text":"Apexificarea"},{"id":"D","text":"Pulpectomia vitală parțială"},{"id":"E","text":"Pulpectomia non-vitală"}],"correct":["A","B","D"],"pages":[420],"source":"set-2"},{"id":"set2-O5Z1CvCg","fingerprint":"74cc9a47a0e089f8","chapterId":"set-2","subchapterId":"set2-5.04","type":"CS","text":"Ce reprezintă apexificarea?","options":[{"id":"A","text":"O metodă de tratament a plăgii dentinare care păstrează în totalitate pulpa vie."},{"id":"B","text":"O procedură de creare a unei bariere apicale la dinții cu necroză pulpară, în absența creșterii radiculare."},{"id":"C","text":"Amputația pulpei coronare pentru a păstra vitalitatea pulpei radiculare."},{"id":"D","text":"Procesul fiziologic de creștere radiculară la dinții permanenți imaturi cu pulpă vie."},{"id":"E","text":"Medicația de elecție utilizată pentru stimularea formării punții de dentină."}],"correct":["B"],"pages":[420],"source":"set-2"},{"id":"set2-Zj5Ak3FT","fingerprint":"71df45e6ac58eae6","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Care sunt proprietățile materialelor de elecție Ca(OH)₂ și MTA, utilizate în tehnicile ce stimulează apexogeneza?","options":[{"id":"A","text":"Adezive"},{"id":"B","text":"Radiotransparente"},{"id":"C","text":"Biostimulatoare"},{"id":"D","text":"Antiseptice"},{"id":"E","text":"Antialgice"}],"correct":["C","D","E"],"pages":[420],"source":"set-2"},{"id":"set2-LgjYGwd2","fingerprint":"5504fcb3e194aac2","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"În ce situație clinică este indicat coafajul indirect la un dinte permanent imatur (DPI)?","options":[{"id":"A","text":"DPI vital cu pulpită reversibilă la primul puseu."},{"id":"B","text":"DPI cu pulpită ireversibilă, manifestată prin durere spontană."},{"id":"C","text":"DPI cu necroză pulpară și leziune periapicală."},{"id":"D","text":"DPI cu deschiderea accidentală a camerei pulpare în timpul preparării cavității."},{"id":"E","text":"DPI vital cu carie simplă profundă, fără deschiderea camerei pulpare."}],"correct":["A","E"],"pages":[420],"source":"set-2"},{"id":"set2-YbhHXZbW","fingerprint":"f966fd243e8f9c06","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Care dintre următoarele elemente reprezintă criterii de succes pentru un coafaj indirect, după perioada de monitorizare de 6-8 săptămâni?","options":[{"id":"A","text":"Păstrarea vitalității pulpare și absența durerii."},{"id":"B","text":"Observarea radiologică a calcificărilor pulpare difuze."},{"id":"C","text":"Apariția semnelor clinice de patologie periapicală."},{"id":"D","text":"Depunerea de dentină de reparație vizibilă pe radiografia periapicală sau bitewing."},{"id":"E","text":"Posibilitatea utilizării dintelui în masticație."}],"correct":["A","D","E"],"pages":[420],"source":"set-2"},{"id":"set2-Qx9q-xTN","fingerprint":"f371df469136df74","chapterId":"set-2","subchapterId":"set2-5.04","type":"CS","text":"Care este caracteristica definitorie a procedurii de coafaj natural?","options":[{"id":"A","text":"Îndepărtarea pulpei coronare și acoperirea pulpei radiculare restante cu o pastă specifică."},{"id":"B","text":"Îndepărtarea completă a dentinei alterate și aplicarea medicației pe o deschidere punctiformă a camerei pulpare."},{"id":"C","text":"Acoperirea cu Ca(OH)₂ a unei cantități mici de dentină alterată lăsată intenționat deasupra cornului pulpar, urmată de reintervenție."},{"id":"D","text":"Reintervenția după 1-6 luni pentru a verifica formarea unei punți dentinare sub materialul aplicat."},{"id":"E","text":"Aplicarea de MTA direct pe peretele dentinar profund, dur și normal colorat, fără prezența dentinei alterate."}],"correct":["C"],"pages":[421],"source":"set-2"},{"id":"set2-2KATO6gU","fingerprint":"2fc59c56144ae1f4","chapterId":"set-2","subchapterId":"set2-5.04","type":"CS","text":"În care dintre următoarele situații clinice este indicat coafajul direct?","options":[{"id":"A","text":"La dinți permanenți imaturi cu pulpită reversibilă la primul puseu, fără episoade repetate de durere provocată."},{"id":"B","text":"În cazul unei deschideri iatrogene a camerei pulpare mai mari de 1 mm."},{"id":"C","text":"La dinți permanenți imaturi cu carie simplă profundă, fără deschiderea camerei pulpare, dar cu dentină alterată restantă."},{"id":"D","text":"În cazul unei deschideri traumatice punctiforme (&lt;1mm) a camerei pulpare, produsă recent (1-6 ore)."},{"id":"E","text":"În situația în care îndepărtarea completă a dentinei alterate ar duce la deschiderea camerei pulpare."}],"correct":["D"],"pages":[421],"source":"set-2"},{"id":"set2-JTfl-QI4","fingerprint":"d9820af0e48f6734","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Care dintre următoarele reprezintă semne de succes ale unui tratament prin coafaj direct?","options":[{"id":"A","text":"Absența resorbției interne."},{"id":"B","text":"Prezența radiologică a unei punți dentinare sub materialul de coafaj după 1-6 luni."},{"id":"C","text":"Păstrarea vitalității pulpare, manifestată prin răspuns normal pozitiv la testele de vitalitate."},{"id":"D","text":"Diferențierea celulelor mezenchimale în osteoclaste ca răspuns la materialul de coafaj."},{"id":"E","text":"Remineralizarea dentinei alterate restante, vizibilă radiologic după 6-8 săptămâni."}],"correct":["A","B","C"],"pages":[421],"source":"set-2"},{"id":"set2-F0dPPtmy","fingerprint":"3ad726380dca6639","chapterId":"set-2","subchapterId":"set2-5.04","type":"CS","text":"Ce definește procedura de pulpotomie?","options":[{"id":"A","text":"Excavații succesive ale dentinei alterate, la un interval de 6-8 săptămâni, pentru a evita deschiderea camerei pulpare."},{"id":"B","text":"Acoperirea unei plăgi dentinare profunde cu hidroxid de calciu pentru a stimula formarea de dentină de reparație."},{"id":"C","text":"Îndepărtarea pulpei coronare și acoperirea pulpei radiculare restante cu o pastă de amputație."},{"id":"D","text":"Îndepărtarea completă atât a pulpei coronare, cât și a celei radiculare."},{"id":"E","text":"Tratamentul unei expuneri pulpare punctiforme (&lt;1mm) cu MTA pentru a menține vitalitatea întregii pulpe."}],"correct":["C"],"pages":[421],"source":"set-2"},{"id":"set2-lT6YvWwX","fingerprint":"6d803f28c7fe2566","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Care dintre următoarele afirmații referitoare la medicația utilizată în tratamentele pulpare conservative sunt corecte?","options":[{"id":"A","text":"Ca(OH)₂ este medicația de elecție pentru coafajul natural."},{"id":"B","text":"MTA este una dintre opțiunile de medicație de elecție pentru coafajul direct."},{"id":"C","text":"Pasta de amputație se utilizează pentru acoperirea pulpei radiculare în pulpotomie."},{"id":"D","text":"MTA este medicația de elecție atât pentru coafajul natural, cât și pentru cel direct."},{"id":"E","text":"Ca(OH)₂ se folosește exclusiv pentru coafajul direct, nu și pentru cel natural."}],"correct":["A","B","C"],"pages":[421],"source":"set-2"},{"id":"set2-KguAV8QK","fingerprint":"22b4277872b2559b","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Ce tipuri de pulpotomie sunt recomandate la dinții permanenți imaturi (DPI)?","options":[{"id":"A","text":"Pulpotomia vitală parțială (Cvek)."},{"id":"B","text":"Pulpotomia cu MTA."},{"id":"C","text":"Pulpotomia vitală totală (cervicală)."},{"id":"D","text":"Pulpotomia devitală."},{"id":"E","text":"Pulpotomia prin tehnica excavațiilor succesive."}],"correct":["A","C"],"pages":[421],"source":"set-2"},{"id":"set2-SHLudVix","fingerprint":"bf4731ddd6da55ce","chapterId":"set-2","subchapterId":"set2-5.04","type":"CS","text":"Care este adâncimea țesutului pulpar coronar îndepărtat în timpul unei pulpotomii vitale parțiale?","options":[{"id":"A","text":"Întregul conținut al camerei pulpare, indiferent de adâncime."},{"id":"B","text":"Mai puțin de 1 mm, doar țesutul superficial expus."},{"id":"C","text":"Întreaga pulpă coronară, până la nivelul orificiilor de intrare în canalele radiculare."},{"id":"D","text":"Atât pulpa coronară, cât și cea radiculară."},{"id":"E","text":"1-3 mm, până se ajunge la pulpa sănătoasă."}],"correct":["E"],"pages":[422],"source":"set-2"},{"id":"set2-p6cquP2S","fingerprint":"9b5156fda41faf70","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Care dintre următoarele reprezintă indicații pentru pulpotomia vitală parțială?","options":[{"id":"A","text":"Dinți permanenți imaturi cu semne clinice și radiologice de pulpită ireversibilă."},{"id":"B","text":"Dinți permanenți imaturi cu deschidere pulpară carioasă de 1-2 mm, unde sângerarea este controlată în 1-2 minute."},{"id":"C","text":"Dinți permanenți imaturi cu fractură coronară penetrantă, când timpul scurs de la traumatism este mai mare de 6 ore și expunerea pulpară este de 1-2 mm."},{"id":"D","text":"Dinți permanenți imaturi cu eșec după un tratament de coafaj pulpar direct."},{"id":"E","text":"Dinți permanenți imaturi cu deschidere accidentală (iatrogenă) a camerei pulpare mai mare de 2 mm."}],"correct":["B","C"],"pages":[422],"source":"set-2"},{"id":"set2-vbDCo9bt","fingerprint":"2a0ff9c1ab8a3ee3","chapterId":"set-2","subchapterId":"set2-5.04","type":"CS","text":"Ce criterii trebuie îndeplinite pentru hemostaza în timpul unei pulpotomii vitale parțiale pentru a putea continua procedura?","options":[{"id":"A","text":"Hemoragia trebuie să se oprească în maximum 1-2 minute după irigarea plăgii cu ser fiziologic."},{"id":"B","text":"Se utilizează peroxid de hidrogen (H₂O₂) până la oprirea completă a sângerării."},{"id":"C","text":"Se aplică presiune cu o buletă uscată timp de 5 minute."},{"id":"D","text":"Se utilizează un vasoconstrictor aplicat direct pe plaga pulpară."},{"id":"E","text":"Sângerarea poate continua pentru o perioadă nedeterminată dacă este de intensitate redusă."}],"correct":["A"],"pages":[422],"source":"set-2"},{"id":"set2-dE_HhqGv","fingerprint":"b53e7af3d3fee862","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Care dintre următoarele elemente sunt considerate semne de succes ale unei pulpotomii vitale parțiale?","options":[{"id":"A","text":"Prezența unei zone de radiotransparență interradiculară."},{"id":"B","text":"Continuarea creșterii rădăcinii și închiderea apexului (apexogeneza) vizibilă radiografic."},{"id":"C","text":"Absența simptomatologiei clinice post-tratament."},{"id":"D","text":"Prezența unui polip pulpar la nivelul expunerii."},{"id":"E","text":"Apariția unei bariere de dentină de reparație sub Ca(OH)₂."}],"correct":["B","C","E"],"pages":[422],"source":"set-2"},{"id":"set2-GEPW3_f_","fingerprint":"11a15fddb5fca7bf","chapterId":"set-2","subchapterId":"set2-5.04","type":"CS","text":"Ce definește procedura de pulpotomie vitală totală?","options":[{"id":"A","text":"Tratamentul unui dinte cu necroză pulpară și afectare periapicală."},{"id":"B","text":"Îndepărtarea completă atât a pulpei coronare, cât și a celei radiculare."},{"id":"C","text":"Acoperirea directă a unei expuneri pulpare punctiforme fără îndepărtare de țesut."},{"id":"D","text":"Îndepărtarea a 1-3 mm de țesut pulpar din zona expunerii."},{"id":"E","text":"Îndepărtarea pulpei coronare îmbolnăvite și păstrarea pulpei radiculare sănătoase."}],"correct":["E"],"pages":[422],"source":"set-2"},{"id":"set2-xItjbKAP","fingerprint":"6a212e832bff88c7","chapterId":"set-2","subchapterId":"set2-5.04","type":"CS","text":"În cazul unui dinte permanent imatur vital, care dintre următoarele situații clinice ar constitui o indicație pentru pulpotomia vitală totală?","options":[{"id":"A","text":"Un dinte care nu prezintă simptomatologie și are camera pulpară intactă."},{"id":"B","text":"O deschidere traumatică a camerei pulpare mai mare de 2 mm."},{"id":"C","text":"Prezența calcificărilor pulpare vizibile radiografic."},{"id":"D","text":"O deschidere carioasă a camerei pulpare de 1-2 mm cu sângerare controlabilă."},{"id":"E","text":"Un dinte cu distrucție coronară mai mare de 2/3 din volumul inițial."}],"correct":["B"],"pages":[422],"source":"set-2"},{"id":"set2-s_J-SiyX","fingerprint":"b690db21b959aa94","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Care dintre următoarele condiții reprezintă contraindicații pentru efectuarea unei pulpotomii vitale totale?","options":[{"id":"A","text":"Dinte cu semne de pulpită ireversibilă sau necroză pulpară."},{"id":"B","text":"Prezența semnelor de afectare interradiculară."},{"id":"C","text":"Eșec după un tratament anterior de coafaj."},{"id":"D","text":"Un pacient cooperant care acceptă procedura de anestezie."},{"id":"E","text":"Dinte cu distrucție coronară mai mare de 2/3 din volumul inițial."}],"correct":["A","B","E"],"pages":[422],"source":"set-2"},{"id":"set2-QLYzjW7f","fingerprint":"ac9534eef90b8bcf","chapterId":"set-2","subchapterId":"set2-5.04","type":"CS","text":"Ce materiale sunt menționate ca fiind de elecție pentru acoperirea plăgii pulpare în pulpotomia vitală parțială?","options":[{"id":"A","text":"Hidroxid de calciu (Ca(OH)₂) sau Agregat Trioxid Mineral (MTA)."},{"id":"B","text":"Ciment cu ionomer de sticlă (CIS) aplicat direct pe pulpă."},{"id":"C","text":"O pastă de amputație pe bază de formocrezol."},{"id":"D","text":"Peroxid de hidrogen (H₂O₂)."},{"id":"E","text":"Ser fiziologic."}],"correct":["A"],"pages":[422],"source":"set-2"},{"id":"set2-Zo0Yhj50","fingerprint":"4a2018b88870b3c4","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Care dintre următoarele criterii indică succesul unei pulpotomii vitale?","options":[{"id":"A","text":"Absența resorbției radiculare patologice și a patologiei periapicale/interradiculare."},{"id":"B","text":"Formarea unei punți dentinare și depunerea de dentină de reparație."},{"id":"C","text":"Absența simptomatologiei și păstrarea vitalității pulpei restante."},{"id":"D","text":"Prezența calcificărilor pulpare radiculare pe imaginea radiografică."},{"id":"E","text":"Continuarea creșterii rădăcinii și edificarea zonei apicale."}],"correct":["A","B","C","E"],"pages":[423],"source":"set-2"},{"id":"set2-xoY7vdW7","fingerprint":"53b7c21feb39305d","chapterId":"set-2","subchapterId":"set2-5.04","type":"CS","text":"Conform protocolului pentru pulpotomia vitală totală, în cât timp trebuie să se oprească hemoragia după irigarea plăgii pulpare?","options":[{"id":"A","text":"Într-un interval de 2-3 minute."},{"id":"B","text":"Într-un interval de 1-3 minute."},{"id":"C","text":"Nu există un interval de timp specificat, importantă fiind doar oprirea sângerării."},{"id":"D","text":"Imediat, în mai puțin de 30 de secunde."},{"id":"E","text":"În maximum 5 minute."}],"correct":["B"],"pages":[423],"source":"set-2"},{"id":"set2-qeR3dNeV","fingerprint":"b5b45300d62c4eda","chapterId":"set-2","subchapterId":"set2-5.04","type":"CS","text":"Ce definește pulpectomia vitală parțială la dinții permanenți imaturi (DPI)?","options":[{"id":"A","text":"Îndepărtarea exclusivă a pulpei coronare până la joncțiunea smalț-cement."},{"id":"B","text":"Stimularea formării unui dop apical de țesut dur într-un dinte devital."},{"id":"C","text":"Îndepărtarea completă a pulpei coronare și radiculare, urmată de obturarea canalelor."},{"id":"D","text":"Aplicarea unui material de coafaj direct pe pulpa coronară expusă pentru a stimula vindecarea."},{"id":"E","text":"Excizia pulpei coronare și a unei părți din pulpa radiculară, păstrând un bont radicular vital extins."}],"correct":["E"],"pages":[423],"source":"set-2"},{"id":"set2-UQ_egkmL","fingerprint":"d41c96559fd263ae","chapterId":"set-2","subchapterId":"set2-5.04","type":"CS","text":"Care este mecanismul principal care stă la baza succesului apexogenezei la dinții permanenți imaturi (DPI)?","options":[{"id":"A","text":"Acțiunea antimicrobiană a materialelor aplicate, precum MTA sau Ca(OH)₂."},{"id":"B","text":"Vascularizația bogată și potențialul celular activ al regiunii apicale largi."},{"id":"C","text":"Capacitatea cimentului cu ionomer de sticlă de a sigila etanș camera pulpară."},{"id":"D","text":"Absența canalelor laterale în treimea apicală a rădăcinilor imature."},{"id":"E","text":"Gradul mare de autonomie funcțională a pulpei coronare."}],"correct":["B"],"pages":[423],"source":"set-2"},{"id":"set2-cRBXfZF_","fingerprint":"feb5881ff95bfdf1","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Care sunt indicațiile corecte pentru pulpectomia vitală parțială la dinții permanenți imaturi (DPI)?","options":[{"id":"A","text":"DPI restaurabil cu pulpită ireversibilă cauzată de carie sau traumatism."},{"id":"B","text":"Orice dinte temporar cu afectare pulpară extinsă."},{"id":"C","text":"DPI cu eșec după o tentativă de pulpotomie."},{"id":"D","text":"DPI cu inflamație pulpară ce depășește pulpa coronară, dar fără afectare periradiculară vizibilă radiologic."},{"id":"E","text":"DPI restaurabil care prezintă pulpă necrozată și semne radiologice de afectare periradiculară."}],"correct":["A","C","D"],"pages":[423],"source":"set-2"},{"id":"set2-xsQTocUp","fingerprint":"b0986a0c4ae0b59b","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Ce aspecte tehnice caracterizează procedura de pulpectomie vitală parțială?","options":[{"id":"A","text":"Se lasă un bont radicular viu cu o lungime de 6-8 mm."},{"id":"B","text":"Pasta de canal trebuie înlocuită periodic pe măsură ce se resoarbe."},{"id":"C","text":"Pulpa radiculară se îndepărtează cu ace Kerr fine pentru a minimiza trauma."},{"id":"D","text":"Se folosește anestezie tronculară periferică sau plexală, obligatoriu cu vasoconstrictor."},{"id":"E","text":"Canalul radicular se lărgește sistematic pentru a asigura o dezinfectare eficientă."}],"correct":["A","B"],"pages":[423],"source":"set-2"},{"id":"set2-Td8C8fxL","fingerprint":"353c9b0e2891f107","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Care sunt indicațiile pentru efectuarea unei pulpectomii non-vitale la dinții permanenți imaturi (DPI)?","options":[{"id":"A","text":"Orice DPI, indiferent de statusul restaurabilității sale protetice."},{"id":"B","text":"DPI cu necroză pulpară."},{"id":"C","text":"Pacienți necooperanți sau care nu pot reveni pentru ședințe multiple de tratament."},{"id":"D","text":"DPI care întrețin complicații infecțioase majore, precum abcese în lojile faciale."},{"id":"E","text":"DPI cu gangrenă pulpară simplă sau complicată cu parodontită apicală."}],"correct":["B","E"],"pages":[424],"source":"set-2"},{"id":"set2-hzIqq22Q","fingerprint":"df48b66d0f0f40c4","chapterId":"set-2","subchapterId":"set2-5.04","type":"CS","text":"Ce reprezintă apexificarea în contextul tratamentului endodontic la dinții permanenți imaturi?","options":[{"id":"A","text":"O metodă prin care se induce formarea unei bariere apicale dure, formată din țesut osteoid, cementoid sau osteo-cementoid, într-o perioadă de 6-24 luni."},{"id":"B","text":"Metoda prin care se continuă formarea rădăcinii și închiderea apexului, proces denumit și apexogeneză."},{"id":"C","text":"O tehnică chirurgicală de sigilare a apexului cu un material biocompatibil, realizată într-o singură ședință."},{"id":"D","text":"Un proces biologic care stimulează teaca lui Hertwig să continue creșterea rădăcinii în lungime și grosime."},{"id":"E","text":"Îndepărtarea pulpei mortificate urmată de revascularizarea imediată a spațiului endodontic."}],"correct":["A"],"pages":[424],"source":"set-2"},{"id":"set2-8fG0hm4p","fingerprint":"cfcf7fbd1dca4522","chapterId":"set-2","subchapterId":"set2-5.04","type":"CS","text":"Care este mecanismul biologic principal care stă la baza procedurii de apexificare?","options":[{"id":"A","text":"Activitatea celulelor nediferențiate din țesutul conjunctiv periapical tânăr, care se diferențiază în osteoblaști, cementoblaști sau odontoblaști."},{"id":"B","text":"Reactivarea tecii epiteliale a lui Hertwig sub acțiunea materialelor de canal, ducând la continuarea edificării radiculare."},{"id":"C","text":"Producerea unui cheag de sânge stabil în interiorul canalului, care servește drept matrice pentru formarea țesutului dur."},{"id":"D","text":"Stimularea directă a odontoblaștilor restanți în treimea apicală a canalului radicular."},{"id":"E","text":"Mineralizarea progresivă a pastei specifice de canal introdusă în spațiul endodontic."}],"correct":["A"],"pages":[424],"source":"set-2"},{"id":"set2-E_D8SFjk","fingerprint":"6f621a26fb6bc869","chapterId":"set-2","subchapterId":"set2-5.04","type":"CS","text":"Care dintre următoarele afirmații descrie corect modificările morfologice ale rădăcinii în urma tratamentului de apexificare?","options":[{"id":"A","text":"Se produce o creștere semnificativă a rădăcinii în lungime și o îngroșare a pereților laterali."},{"id":"B","text":"Lungimea rădăcinii rămâne constantă, dar pereții radiculari se îngroașă considerabil."},{"id":"C","text":"Grosimea pereților laterali radiculari și lungimea totală a rădăcinii rămân nemodificate."},{"id":"D","text":"Morfologia apicală devine întotdeauna ascuțită și bine definită radiologic."},{"id":"E","text":"Apare o resorbție radiculară externă controlată care contribuie la conformarea apexului."}],"correct":["C"],"pages":[424],"source":"set-2"},{"id":"set2-x4Py7s5O","fingerprint":"a6cfe64277049f03","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Care dintre următoarele reprezintă criterii de succes pentru o pulpectomie non-vitală a dinților permanenți imaturi?","options":[{"id":"A","text":"Continuarea creșterii rădăcinii în lungime și grosime, vizibilă radiologic."},{"id":"B","text":"Lipsa complicațiilor periapicale, cum ar fi abcesul, celulita sau fistula."},{"id":"C","text":"Absența simptomatologiei."},{"id":"D","text":"Menținerea apexului deschis pentru a permite revascularizarea ulterioară."},{"id":"E","text":"Absența altor semne clinice sau radiologice de parodontită apicală."}],"correct":["B","C","E"],"pages":[424],"source":"set-2"},{"id":"set2-wTpxq_uC","fingerprint":"afd0b81e7200bf00","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Care sunt obiectivele tratamentului de apexificare?","options":[{"id":"A","text":"Reactivarea tecii lui Hertwig pentru a finaliza dezvoltarea radiculară."},{"id":"B","text":"Închiderea apexului, care este evaluată radiologic."},{"id":"C","text":"Utilizarea dintelui în masticație."},{"id":"D","text":"Stimularea creșterii în lungime a rădăcinii."},{"id":"E","text":"Prevenirea apariției resorbției radiculare."}],"correct":["B","C","E"],"pages":[424],"source":"set-2"},{"id":"set2-Doh1vinR","fingerprint":"6063292ec9fea793","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Care dintre următoarele substanțe pot fi amestecate cu hidroxidul de calciu (Ca(OH)₂) pentru utilizarea în tratamentele de apexificare?","options":[{"id":"A","text":"Soluție Ringer"},{"id":"B","text":"Ser fiziologic"},{"id":"C","text":"MTA"},{"id":"D","text":"Acetatul de metacresil (Cresatin)"},{"id":"E","text":"Pastă cu antibiotice"}],"correct":["A","B","D"],"pages":[425],"source":"set-2"},{"id":"set2-AjeetKQj","fingerprint":"f9157eec8bf68621","chapterId":"set-2","subchapterId":"set2-5.04","type":"CS","text":"Ce etapă urmează după realizarea cu succes a apexificării la un dinte permanent imatur?","options":[{"id":"A","text":"Se realizează pulpectomia non-vitală."},{"id":"B","text":"Canalul se obturează cu pastă definitivă și conuri de gutapercă, apoi se reface morfologia coronară."},{"id":"C","text":"Se efectuează calibrarea (lărgirea) canalului pentru a permite o obturație mai bună."},{"id":"D","text":"Se continuă cu reintervenții pe canal pentru înlocuirea pastei bioactive."},{"id":"E","text":"Se sterilizează canalul radicular și se sigilează etanș cu o obturație coronară provizorie."}],"correct":["B"],"pages":[425],"source":"set-2"},{"id":"set2-xAPJu4O7","fingerprint":"2b3748411de6a115","chapterId":"set-2","subchapterId":"set2-5.04","type":"CS","text":"Ce dificultate terapeutică majoră este asociată cu aspectul de 'lumânare inversată' al canalului radicular la dinții permanenți imaturi cu apexuri divergente?","options":[{"id":"A","text":"Modificarea nefavorabilă a proporției coroană/rădăcină."},{"id":"B","text":"Predispoziția rădăcinilor la fracturi cervicale și verticale."},{"id":"C","text":"Risc crescut de depășire periapicală a obturației de canal."},{"id":"D","text":"Imposibilitatea obținerii unui suport pentru obturația definitivă de canal."},{"id":"E","text":"Evacuarea completă a conținutului mortificat și infectat al canalului."}],"correct":["E"],"pages":[425],"source":"set-2"},{"id":"set2-L4kCmaYN","fingerprint":"1d4f1d3ba77268f7","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Care sunt implicațiile clinico-terapeutice ale prezenței pereților radiculari subțiri la dinții permanenți imaturi?","options":[{"id":"A","text":"Există un risc crescut de depășire periapicală a obturației de canal."},{"id":"B","text":"Se recomandă evitarea calibrării (lărgirii) canalului."},{"id":"C","text":"Rădăcinile sunt predispuse la frecvente fracturi cervicale și verticale."},{"id":"D","text":"Se produce o modificare nefavorabilă a proporției coroană/rădăcină."},{"id":"E","text":"Evacuarea conținutului infectat al canalului este foarte dificilă."}],"correct":["B","C"],"pages":[425],"source":"set-2"},{"id":"set2-l83zsYFi","fingerprint":"3bcd15c76297402a","chapterId":"set-2","subchapterId":"set2-5.04","type":"CS","text":"Care dintre următoarele afirmații descrie un avantaj al apexificării cu hidroxid de calciu (Ca(OH)₂)?","options":[{"id":"A","text":"Necesită un număr redus de ședințe și un timp scurt de tratament."},{"id":"B","text":"Este o metodă complexă și costisitoare, dar cu rezultate predictibile."},{"id":"C","text":"Stimulează creșterea în lungime a rădăcinii și îngroșarea pereților dentinari."},{"id":"D","text":"Induce formarea unei bariere apicale dure ce oferă suport pentru obturația definitivă."},{"id":"E","text":"Minimizează riscul de infectare a canalului pe parcursul tratamentului."}],"correct":["D"],"pages":[425],"source":"set-2"},{"id":"set2-6cIjuFl_","fingerprint":"02bd1c20e092061d","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Care sunt dezavantajele utilizării hidroxidului de calciu (Ca(OH)₂) în procedura de apexificare?","options":[{"id":"A","text":"Timpul îndelungat necesar pentru obținerea barierei apicale."},{"id":"B","text":"Necesitatea unor numeroase reintervenții pe canal pentru înlocuirea pastei."},{"id":"C","text":"Inducerea unei bariere apicale slabe, care nu oferă suport pentru obturație."},{"id":"D","text":"Costul ridicat al materialului și complexitatea tehnicii."},{"id":"E","text":"Riscul crescut de fracturi radiculare din cauza lipsei îngroșării pereților dentinari."}],"correct":["A","B","E"],"pages":[425],"source":"set-2"},{"id":"set2-NM6LfRyV","fingerprint":"fa84b788844aa042","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Care sunt dezavantajele asociate cu procedura de apexificare cu MTA?","options":[{"id":"A","text":"Bariera apicală se obține într-un interval lung de timp."},{"id":"B","text":"Riscul crescut de fracturi radiculare."},{"id":"C","text":"Nu oferă un suport adecvat pentru obturația de canal."},{"id":"D","text":"Este o metodă complexă și costisitoare."},{"id":"E","text":"Necesită un număr mare de ședințe de tratament."}],"correct":["B","D"],"pages":[426],"source":"set-2"},{"id":"set2-DpfuK0Jg","fingerprint":"6f4fda68a8896c58","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Care sunt avantajele terapiei endodontice de regenerare (revascularizare)?","options":[{"id":"A","text":"Creșterea rădăcinii și închiderea apexului."},{"id":"B","text":"Presupune o singură ședință de tratament."},{"id":"C","text":"Este o procedură neinvazivă și cu risc scăzut la complicații."},{"id":"D","text":"Îngroșarea pereților radiculari."},{"id":"E","text":"Este o metodă cu costuri reduse."}],"correct":["A","C","D"],"pages":[426],"source":"set-2"},{"id":"set2-O1w_xQFE","fingerprint":"cea9f27e4d0196ca","chapterId":"set-2","subchapterId":"set2-5.04","type":"CS","text":"Prin ce se diferențiază revascularizarea de apexificarea cu MTA în ceea ce privește dezvoltarea ulterioară a rădăcinii?","options":[{"id":"A","text":"Ambele proceduri duc la o dezvoltare radiculară similară, dar revascularizarea este mai rapidă."},{"id":"B","text":"Revascularizarea permite creșterea rădăcinii și îngroșarea pereților radiculari, spre deosebire de apexificare."},{"id":"C","text":"Doar apexificarea cu MTA permite închiderea naturală a apexului."},{"id":"D","text":"Niciuna dintre proceduri nu influențează dezvoltarea ulterioară a rădăcinii."},{"id":"E","text":"Apexificarea cu MTA stimulează îngroșarea pereților radiculari, în timp ce revascularizarea nu."}],"correct":["B"],"pages":[426],"source":"set-2"},{"id":"set2-5EgeJqe4","fingerprint":"d6e276d028253ecc","chapterId":"set-2","subchapterId":"set2-5.04","type":"CS","text":"În cadrul terapiei de revascularizare, care este rolul principal al cheagului de sânge indus în canalul radicular?","options":[{"id":"A","text":"Să acționeze ca o matrice pentru regenerarea țesutului pulpar."},{"id":"B","text":"Să servească drept obturație de canal definitivă."},{"id":"C","text":"Să oprească sângerarea din zona periapicală."},{"id":"D","text":"Să formeze un \"dop\" apical similar cu cel de MTA."},{"id":"E","text":"Să dezinfecteze spațiul endodontic prin acțiune antimicrobiană."}],"correct":["A"],"pages":[426],"source":"set-2"},{"id":"set2-rA7--9Nm","fingerprint":"5d9dc74b98b365a1","chapterId":"set-2","subchapterId":"set2-5.04","type":"CS","text":"Care dintre următoarele afirmații descrie corect un pas specific din protocolul de revascularizare?","options":[{"id":"A","text":"Se aplică o pastă cu 3 antibiotice după dezinfecția prin irigații."},{"id":"B","text":"Procedura se finalizează în aceeași ședință cu obturația de canal definitivă."},{"id":"C","text":"Sângerarea în canal este un accident procedural care trebuie evitat."},{"id":"D","text":"Se realizează instrumentarea mecanică riguroasă a canalului pentru a elimina țesutul necrotic."},{"id":"E","text":"Se introduce un \"dop\" de MTA în apex pentru a bloca mecanic canalul."}],"correct":["A"],"pages":[426],"source":"set-2"},{"id":"set2-BwPqqhW5","fingerprint":"716e8958c780ce77","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Care sunt particularitățile structurale și morfologice ale dinților permanenți imaturi care le influențează vulnerabilitatea la caria dentară?","options":[{"id":"A","text":"Camera pulpară are dimensiuni reduse, iar coarnele pulpare sunt situate profund, scăzând riscul de expunere accidentală."},{"id":"B","text":"Defectele de coalescență și de structură sunt rar întâlnite la nivelul molarilor și premolarilor."},{"id":"C","text":"Smalțul prezintă un proces de maturare posteruptivă care continuă timp de 2-3 ani după erupție."},{"id":"D","text":"Canaliculele dentinare largi cresc permeabilitatea pentru germeni microbieni, preparate pe bază de hidroxid de calciu și monomeri."},{"id":"E","text":"Pereții camerei pulpare se subțiază progresiv prin procesul de maturare posteruptivă."}],"correct":["C","D"],"pages":[406],"source":"set-2"},{"id":"set2-iZlQBMb3","fingerprint":"40819e7a8f5b12bd","chapterId":"set-2","subchapterId":"set2-5.04","type":"CS","text":"Referitor la distribuția topografică și epidemiologică a leziunilor carioase la nivelul dinților permanenți imaturi, este valabilă următoarea afirmație:","options":[{"id":"A","text":"La vârsta de 6-7 ani, dinții maxilari prezintă un grad mai mare de afectare cariosă comparativ cu cei mandibulari."},{"id":"B","text":"Începând cu vârsta de 10 ani, frecvența leziunilor carioase devine mai importantă la nivelul arcadei maxilare."},{"id":"C","text":"Incisivii centrali superiori prezintă o rezistență crescută la carie, similară cu cea a frontalilor inferiori și a caninilor."},{"id":"D","text":"Grupul dentar cel mai vulnerabil la atacul carios este reprezentat de molarii secunzi, urmați de primii molari."},{"id":"E","text":"Băieții prezintă, la nivelul vârstei de 13 ani, un număr mai mare de suprafețe cariate comparativ cu fetele."}],"correct":["B"],"pages":[406],"source":"set-2"},{"id":"set2-iYrlTrDN","fingerprint":"89cedec0b2950f2b","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Clasificarea clinică a cariilor simple la dinții permanenți imaturi în funcție de profunzimea leziunii include următoarele categorii:","options":[{"id":"A","text":"Cariile medii, extinse între 0,5 mm peste joncțiunea smalț-dentină și până la o distanță de 0,5 mm de camera pulpară."},{"id":"B","text":"Cariile incipiente, cu afectare strictă a treimii externe a smalțului, fără atingerea joncțiunii smalț-dentină."},{"id":"C","text":"Cariile penetrante, care implică expunerea punctiformă a unuia dintre coarnele pulpare."},{"id":"D","text":"Cariile profunde, definite printr-o grosime a dentinei restante până la pulpă mai mică de 0,5 mm."},{"id":"E","text":"Cariile superficiale, caracterizate prin afectarea smalțului și o penetrare de maximum 0,5 mm în dentină."}],"correct":["A","D","E"],"pages":[407],"source":"set-2"},{"id":"set2-etGtyrSK","fingerprint":"3781639383563017","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"În evaluarea clinică și paraclinică a cariei necavitare a smalțului pe suprafețele accidentate (ocluzale), sunt observate următoarele aspecte:","options":[{"id":"A","text":"Utilizarea unei sonde ascuțite în timpul palpării este recomandată pentru decelarea gradului de aderență a structurilor dure."},{"id":"B","text":"Procesul carios debutează prin două leziuni separate situate pe pereții laterali ai șanțului, care confluează ulterior atingerii joncțiunii smalț-dentină."},{"id":"C","text":"Examinarea radiografică nu este utilă pentru diagnosticul acestui tip specific de carie incipientă."},{"id":"D","text":"Modificările decelabile la nivelul bazei șanțului indică penetrarea procesului carios în dentină."},{"id":"E","text":"Baza șanțului ocluzal prezintă modificări demineralizante evidente înaintea afectării versanților laterali."}],"correct":["B","C","D"],"pages":[407],"source":"set-2"},{"id":"set2-9CutvF_D","fingerprint":"a0fe356df0dfff3a","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Care sunt semnele clinice și paraclinice caracteristice cariei avansate în dentină la dinții permanenți imaturi?","options":[{"id":"A","text":"Decelarea unei dentine alterate de aspect umed și o colorație alb-gălbuie indică o evoluție cronică a procesului carios."},{"id":"B","text":"Prezența unei dureri spontane, cu iradiere, care persistă după îndepărtarea agentului cauzal."},{"id":"C","text":"Depistarea leziunilor carioase proximale situate sub punctul de contact se realizează eficient prin utilizarea sondei 17."},{"id":"D","text":"Percuția în ax este de obicei negativă, iar camera pulpară este închisă la palparea cu sonda."},{"id":"E","text":"Testele de vitalitate generează un răspuns normal pozitiv, însă pot oferi rezultate eronate în cazul copiilor."}],"correct":["C","D","E"],"pages":[408],"source":"set-2"},{"id":"set2-e_072Lvm","fingerprint":"cfeb02565659d9f1","chapterId":"set-2","subchapterId":"set2-5.04","type":"CS","text":"În managementul terapeutic al cariei simple foarte profunde la un dinte permanent imatur, atitudinea recomandată pentru prevenirea expunerii pulpare accidentale constă în:","options":[{"id":"A","text":"Aplicarea tehnicilor de excavație succesivă și conservarea unei mici cantități de dentină alterată în proximitatea cornului pulpar, urmată de un coafaj natural."},{"id":"B","text":"Îndepărtarea smalțului demineralizat de la nivelul pereților laterali ai șanțului ocluzal prin enameloplastie."},{"id":"C","text":"Extirparea vitală imediată a pulpei dentare pentru a preveni complicațiile periapicale asociate anatomiei cu apex deschis."},{"id":"D","text":"Efectuarea unei pulpotomii parțiale cu scopul de a menține vitalitatea pulpei radiculare și de a permite finalizarea apexogenezei."},{"id":"E","text":"Realizarea exerezei totale a dentinei alterate, urmată de un coafaj direct cu hidroxid de calciu pentru stimularea maturogenezei."}],"correct":["A"],"pages":[409],"source":"set-2"},{"id":"set2-H3dLsiqr","fingerprint":"407013ea909154f1","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Care sunt afirmațiile adevărate privind prepararea cavităților la dinții permanenți imaturi?","options":[{"id":"A","text":"Principiul de bază este economia de substanță dentară sănătoasă."},{"id":"B","text":"Principiul extensiei preventive a fost înlocuit cu principiul sigilării preventive în prepararea cavităților ocluzale minime."},{"id":"C","text":"Tratamentul cariei simple are ca obiective principale păstrarea vitalității pulpare și conservarea structurii dure dentare."},{"id":"D","text":"Tehnica minim-invazivă permite obținerea exclusivă de preparații extinse în dentină."},{"id":"E","text":"Pentru pacienții necooperanți de orice vârstă este indicată utilizarea tehnicilor clasice de preparare."}],"correct":["A","B","C"],"pages":[409],"source":"set-2"},{"id":"set2-Hpl3Vw_E","fingerprint":"1d73b843bfc2b7e1","chapterId":"set-2","subchapterId":"set2-5.04","type":"CS","text":"Care este caracteristica morfologică a cavității clasa I conservatoare în smalț și limitat în dentină?","options":[{"id":"A","text":"Prezintă o lățime cuprinsă între 2 și 3 mm."},{"id":"B","text":"Unghiurile dentinare interne sunt menținute ascuțite pentru retenție."},{"id":"C","text":"Adâncimea cavității depășește cu puțin joncțiunea smalț-dentină."},{"id":"D","text":"Pereții laterali sunt divergenți spre ocluzal."},{"id":"E","text":"Se obține prin exereza exclusivă a dentinei, păstrând smalțul intact."}],"correct":["C"],"pages":[410],"source":"set-2"},{"id":"set2-fgt5Og1g","fingerprint":"af21de887a393cf4","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Care dintre următoarele tipuri de preparări reprezintă cavități proximale clasa a II-a conservatoare?","options":[{"id":"A","text":"Cavitatea tip tunel."},{"id":"B","text":"Cavitatea tip fereastră ocluzală."},{"id":"C","text":"Cavitatea tip casetă."},{"id":"D","text":"Cavitatea verticală redusă."},{"id":"E","text":"Cavitatea orizontală lărgită."}],"correct":["A","C","D"],"pages":[410],"source":"set-2"},{"id":"set2-hH9SWo97","fingerprint":"e17f1189c74bed80","chapterId":"set-2","subchapterId":"set2-5.04","type":"CS","text":"Care este abordarea terapeutică indicată în cazul unei carii proximale cavitare mici, cu creasta marginală integră și groasă de minim 2 mm, inobservabilă clinic, dar cu dinte vecin prezent?","options":[{"id":"A","text":"Prepararea unei cavități tip șanț cu acces dinspre vestibular sau oral."},{"id":"B","text":"Prepararea unei cavități ultraconservatoare ocluzale prin enameloplastie strictă."},{"id":"C","text":"Prepararea unei cavități verticale reduse cu abordare dinspre creasta marginală."},{"id":"D","text":"Prepararea unei cavități tip casetă cu acces direct dinspre proximal."},{"id":"E","text":"Prepararea unei cavități tip tunel cu acces dinspre foseta ocluzală proximală."}],"correct":["E"],"pages":[411],"source":"set-2"},{"id":"set2-brmW8uEP","fingerprint":"d5079b972f8c00c6","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Care sunt particularitățile tehnice ale preparării unei cavități verticale reduse de clasa a II-a?","options":[{"id":"A","text":"Unghiurile dentinare interne sunt modelate ascuțit pentru a crește retenția micromecanică."},{"id":"B","text":"Accesul se realizează direct dinspre vestibular, lăsând creasta marginală integră."},{"id":"C","text":"Pereții laterali sunt preparați convergenți spre ocluzal și divergenți spre dintele vecin."},{"id":"D","text":"Pragul gingival se plasează la 0,5 mm sub punctul de contact și prezintă o formă ușor concavă."},{"id":"E","text":"Se prepară obligatoriu o retenție ocluzală suplimentară pentru a asigura stabilitatea mecanică."}],"correct":["C","D"],"pages":[411],"source":"set-2"},{"id":"set2-avGkGD9i","fingerprint":"b83ee906eaabb9de","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Care dintre următoarele caracteristici asigură forma de rezistență în cazul preparării cavităților prin tehnica clasică modificată?","options":[{"id":"A","text":"Unghiul cavo-suprafață de 90º la cavitățile de clasa I și a II-a."},{"id":"B","text":"Grosimea minimă de 0,5 mm a pereților laterali la cavitățile de clasa a III-a, a IV-a și a V-a."},{"id":"C","text":"Adâncimea minimă a cavității de 0,5 mm în dentină."},{"id":"D","text":"Pereții meziali și distali convergenți spre ocluzal în cavitatea de clasa I."},{"id":"E","text":"Menținerea bolților cuspidiene foarte nesusținute prin căptușire cu ciment ionomer de sticlă."}],"correct":["A","B","C"],"pages":[412],"source":"set-2"},{"id":"set2-BmznpgUw","fingerprint":"f143eb3de007ac53","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Care sunt regulile aplicate pentru realizarea extensiei preventive în tehnica clasică modificată de preparare a cavităților?","options":[{"id":"A","text":"Extensia preventivă pentru cavitățile de clasa a III-a se realizează strict din considerente estetice, prin îndepărtarea smalțului colorat marginal."},{"id":"B","text":"La cavitățile de clasa a VI-a, se aplică o extensie preventivă extinsă pentru a îngloba fisurile de pe vârful cuspizilor."},{"id":"C","text":"La cavitățile de clasa a II-a, pragul gingival se înfundă cu 1 mm sub punctul de contact."},{"id":"D","text":"La cavitățile de clasa I, marginile se aduc pe pantele cuspidiene, în zone cu risc mic la carie."},{"id":"E","text":"Pentru cavitățile de clasa a II-a, pereții laterali verticali se scot în afara punctului de contact cu dintele vecin cu 0,5 mm."}],"correct":["A","D","E"],"pages":[412],"source":"set-2"},{"id":"set2-J9Jdv50G","fingerprint":"f302671df47ab4b1","chapterId":"set-2","subchapterId":"set2-5.04","type":"CS","text":"În care dintre următoarele situații clinice este indicată exereza parțială a dentinei alterate în cadrul preparării cavităților?","options":[{"id":"A","text":"Distrucții coronare mari ce necesită aplicarea unor mijloace suplimentare de retenție."},{"id":"B","text":"Carii proximale cu creasta marginală întreruptă."},{"id":"C","text":"Carii simple foarte profunde, pentru a evita deschiderea camerei pulpare."},{"id":"D","text":"Carii cavitare cu extindere mare în dentină la copii necooperanți tratați prin tehnica ART."},{"id":"E","text":"Carii cu extindere laterală mare în dentină de-a lungul joncțiunii smalț-dentină cu risc carios mic."}],"correct":["C"],"pages":[412],"source":"set-2"},{"id":"set2-neJ4-ZvT","fingerprint":"c1d208197137839a","chapterId":"set-2","subchapterId":"set2-5.04","type":"CS","text":"De ce este recomandată temporizarea utilizării știfturilor sau a puțurilor parapulpare pentru cavitățile de clasa a IV-a pe dinții permanenți imaturi?","options":[{"id":"A","text":"Cimenturile utilizate frecvent nu fac priză corespunzătoare în prezența elementelor parapulpare la dinții tineri."},{"id":"B","text":"Smalțul nesusținut de dentină este prea subțire și se fracturează ușor sub presiunea știftului."},{"id":"C","text":"Rădăcina incomplet formată nu permite o distribuție echilibrată a forțelor ocluzale transmise de știft."},{"id":"D","text":"Dinții permanenți imaturi prezintă o cameră pulpară voluminoasă și coarne pulpare superficiale, generând un risc crescut de deschidere a camerei pulpare."},{"id":"E","text":"Aderența la dentina dinților imaturi este insuficientă pentru reținerea puțurilor parapulpare."}],"correct":["D"],"pages":[413],"source":"set-2"},{"id":"set2-uy0phNie","fingerprint":"30328ae1ce5a4424","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Cum sunt abordate șanțurile și fisurile marginale restante retentive în cazul preparării unei cavități de clasa I modificate, în funcție de gradul de risc la carie al pacientului?","options":[{"id":"A","text":"La pacienții cu risc mediu, extensia preventivă este limitată, iar șanțurile restante se sigilează."},{"id":"B","text":"La pacienții cu risc mare, șanțurile restante se exclud din preparație, preferându-se aplicarea exclusivă a agenților fluoruranți."},{"id":"C","text":"La pacienții cu risc mic, șanțurile restante sunt înglobate în conturul extern al cavității pentru a preveni recidiva."},{"id":"D","text":"La pacienții cu risc mare, șanțurile și fisurile restante se înglobează în conturul extern al cavității."},{"id":"E","text":"La toți pacienții, indiferent de risc, șanțurile restante retentive se înglobează obligatoriu în preparație."}],"correct":["A","D"],"pages":[412],"source":"set-2"},{"id":"set2-KtfWPB83","fingerprint":"dc372860494c5e22","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Care dintre următoarele afirmații descriu corect principiile și indicațiile preparării cavităților prin tehnica ART (Atraumatic Restorative Treatment)?","options":[{"id":"A","text":"Tehnica utilizează exclusiv instrumentar rotativ la turații joase pentru îndepărtarea dentinei alterate."},{"id":"B","text":"Este indicată la copii și adolescenți necooperanți de orice vârstă, indiferent de prezența sau absența unor dizabilități."},{"id":"C","text":"Obturarea cavităților rezultate se realizează în mod clasic utilizând amalgam de argint sau compozite de tip bulk-fill."},{"id":"D","text":"Instrumentarul de bază folosit pentru prepararea cavității include dalta de smalț, excavatorul și lingura Black."},{"id":"E","text":"Tehnica vizează exclusiv cariile necavitare aflate în stadiul incipient de maculă cretoasă."}],"correct":["B","D"],"pages":[414],"source":"set-2"},{"id":"set2-s1IGeyYv","fingerprint":"088be955731d46e8","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Care dintre următoarele reprezintă obiective ale tratamentului plăgii dentinare?","options":[{"id":"A","text":"Sigilarea canaliculelor dentinare expuse prin prepararea cavității, utilizând lineri, lacuri sau adezivi."},{"id":"B","text":"Protecția fizică împotriva deshidratării și a acizilor proveniți din materialele folosite."},{"id":"C","text":"Protecția chimică față de agenții termici și electrici."},{"id":"D","text":"Protecția biologică împotriva invaziei bacteriene și a toxinelor acestora."},{"id":"E","text":"Obținerea unui efect antibacterian și stimularea neodentinogenezei."}],"correct":["A","D","E"],"pages":[414],"source":"set-2"},{"id":"set2--UHAVEe9","fingerprint":"0dd4113cc309c407","chapterId":"set-2","subchapterId":"set2-5.04","type":"CS","text":"Care este protocolul corect pentru realizarea toaletei în cazul cavităților profunde premergător tratamentului plăgii dentinare?","options":[{"id":"A","text":"Toaleta prin irigare abundentă cu hipoclorit de sodiu și acid citric."},{"id":"B","text":"Spălarea cavității cu o soluție mixtă de alcool și peroxid de hidrogen."},{"id":"C","text":"Irigarea și curățarea exclusivă cu peroxid de hidrogen."},{"id":"D","text":"Curățarea suprafeței dentinare cu alcool în scopul unei deshidratări prompte și decontaminării stratului profund."},{"id":"E","text":"Spălarea cavității utilizând ser fiziologic sau apă distilată."}],"correct":["E"],"pages":[414],"source":"set-2"},{"id":"set2-zGGkTmk_","fingerprint":"58b3ffea294c29ad","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Care dintre următoarele afirmații descriu corect metodele de tratament al plăgii dentinare și protecția pulpară?","options":[{"id":"A","text":"Coafajul natural necesită o durată de menținere a materialului de cel puțin 6-8 săptămâni în vederea inițierii și derulării neodentinogenezei."},{"id":"B","text":"Coafajul indirect este indicat cu precădere în cavitățile superficiale situate la nivelul smalțului."},{"id":"C","text":"Coafajul natural constituie un derivat al coafajului indirect aplicat atunci când înlăturarea ultimei porțiuni de dentină alterată ar provoca o expunere pulpară accidentală."},{"id":"D","text":"Coafajul direct se utilizează în prezența cariilor profunde care au condus la o deschidere punctiformă a camerei pulpare la nivelul unui corn pulpar."},{"id":"E","text":"Tehnica excavațiilor succesive (step-wise technique) impune realizarea coafajului natural o singură dată pentru evitarea iritației pulpare adiționale."}],"correct":["A","C","D"],"pages":[414],"source":"set-2"},{"id":"set2-8ct14uMQ","fingerprint":"2f3e72155c39133c","chapterId":"set-2","subchapterId":"set2-5.04","type":"CS","text":"Care sunt caracteristicile clinice și terapeutice specifice unei cavități de clasa I conservatoare cu indicație pentru o obturație preventivă cu rășină tip 2 (OPR 2)?","options":[{"id":"A","text":"Preparația implică o extindere laterală vastă în dentină, intră în contact cu dintele antagonist și corespunde unei cavități profunde."},{"id":"B","text":"Tratamentul restaurator impune de la bun început realizarea unei baze protectoare din ciment ionomer de sticlă urmată de un strat din rășină compozită densă."},{"id":"C","text":"Leziunea se prezintă sub forma unei preparări ultraconservatoare abordate prin obturare cu material compozit fluid și sigilare generală a șanțurilor și fosetelor."},{"id":"D","text":"Cavitatea se rezumă la smalț și 0,5 mm la nivelul dentinei, prezentând o extindere laterală minimă și absența punctelor de contact ocluzal cu antagonistul."},{"id":"E","text":"Cavitatea prezintă indicație absolută pentru un coafaj indirect cu preparate pe bază de hidroxid de calciu [Ca(OH)₂] anterior aplicării obturației de bază."}],"correct":["D"],"pages":[415],"source":"set-2"},{"id":"set2-r9-WNs-0","fingerprint":"9a2396b63b091d82","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Care dintre asocierile prezentate reflectă o conduită terapeutică adecvată în cadrul tratamentului restaurator al cavităților de clasa a II-a preparate prin tehnici minim-invazive?","options":[{"id":"A","text":"Cavitate preparată prin tehnica clasică modificată: se indică tratamentul plăgii dentinare cu finalizare limitată strict la folosirea amalgamului dentar de argint."},{"id":"B","text":"Cavitate clasa a II-a minim invazivă tip șanț: se completează tratamentul plăgii dentinare cu realizarea unei obturații pe bază de ciment ionomer de sticlă condensabil."},{"id":"C","text":"Cavitate clasa a II-a tip tunel: se recurge la tratamentul plăgii dentinare însoțit de aplicarea unei obturații laminate formate din ciment ionomer de sticlă și compozit."},{"id":"D","text":"Cavitate clasa a II-a minim invazivă tip casetă: tratamentul plăgii dentinare este urmat de inserarea unei obturații din compozit, compomer sau ciment ionomer de sticlă."},{"id":"E","text":"Cavitate clasa a II-a minim invazivă verticală redusă: se acoperă teritoriul preparat exclusiv cu o obturație de bază permanentă din ciment fosfat de zinc (FOZ)."}],"correct":["B","C","D"],"pages":[415],"source":"set-2"},{"id":"set2-atNEclah","fingerprint":"9107330cba28a243","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Care sunt particularitățile morfo-structurale ale pulpei și rădăcinii dinților permanenți imaturi?","options":[{"id":"A","text":"Pereții radiculari vestibulari și orali se dezvoltă mai repede decât cei meziali și distali."},{"id":"B","text":"Substanța fundamentală dispune de un grad ridicat de hidratare, permițând păstrarea unei presiuni intrapulpare constante timp îndelungat."},{"id":"C","text":"Pragul dureros la testarea electrometrică este scăzut din cauza integrării complete a fibrelor nervoase."},{"id":"D","text":"Canalele radiculare sunt mai înguste în sens vestibulo-oral comparativ cu sensul mezio-distal."},{"id":"E","text":"Pulpa prezintă o cantitate redusă de fibre de colagen."}],"correct":["B","E"],"pages":[415],"source":"set-2"},{"id":"set2-GaUid4k9","fingerprint":"c3b0e96045621d86","chapterId":"set-2","subchapterId":"set2-5.04","type":"CS","text":"În care dintre următoarele forme clinice de inflamație pulpară percuția în ax se prezintă pozitivă?","options":[{"id":"A","text":"Pulpita acută seroasă totală"},{"id":"B","text":"Hiperemia preinflamatorie"},{"id":"C","text":"Pulpita acută seroasă parțială în faza de debut"},{"id":"D","text":"Pulpitele ireversibile cronice"},{"id":"E","text":"Pulpita purulentă parțială"}],"correct":["A"],"pages":[415],"source":"set-2"},{"id":"set2-UzJ4KUuu","fingerprint":"3acb3b3846ddefb9","chapterId":"set-2","subchapterId":"set2-5.04","type":"CS","text":"Care este evoluția temporală a durerii în pulpita acută seroasă parțială în faza de debut, în urma îndepărtării stimulului termic sau chimic?","options":[{"id":"A","text":"Durerea se prelungește până la 10-15 minute după îndepărtarea stimulului."},{"id":"B","text":"Durerea durează frecvent o noapte întreagă și nu cedează la antialgicele obișnuite."},{"id":"C","text":"Durerea cedează imediat după înlăturarea stimulului provocator."},{"id":"D","text":"Durerea se prelungește 1-2 minute după îndepărtarea stimulului."},{"id":"E","text":"Durerea se instalează sub formă de crize care durează constant câteva ore."}],"correct":["A"],"pages":[416],"source":"set-2"},{"id":"set2-Ob59R5Dr","fingerprint":"88fc740f8c55a57f","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Care dintre următoarele entități patologice aparțin clasei pulpitelor ireversibile în patologia dinților permanenți imaturi?","options":[{"id":"A","text":"Pulpita acută seroasă parțială în stadiul 1"},{"id":"B","text":"Pulpita seroasă totală"},{"id":"C","text":"Hiperemia pulpară"},{"id":"D","text":"Pulpita acută seroasă parțială în stadiul 2 de evoluție"},{"id":"E","text":"Pulpitele purulente"}],"correct":["B","D","E"],"pages":[415],"source":"set-2"},{"id":"set2-wXCarRmq","fingerprint":"c28e25d9fbb4e8df","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Care sunt manifestările clinice și obiective definitorii ale pulpitei purulente parțiale diagnosticate pe un dinte permanent imatur?","options":[{"id":"A","text":"Durerile sunt exacerbate exclusiv de expunerea la agenți fizici reci."},{"id":"B","text":"Durerile apar spontan, cu o frecvență crescută noaptea, fiind provocate de factori termici calzi."},{"id":"C","text":"Durerile au un caracter pulsatil, desfășurându-se sincron cu pulsul vascular."},{"id":"D","text":"Percuția în ax este marcat pozitivă."},{"id":"E","text":"Durerile sunt exacerbate secundar creșterii afluxului sanguin în regiunea cefalică."}],"correct":["B","C","E"],"pages":[417],"source":"set-2"},{"id":"set2-x9yYMlen","fingerprint":"8d4c89c59c14debf","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Aspectul sângerării pulpare în urma investigării directe prezintă trăsături distinctive esențiale diagnosticului diferențial. Care dintre următoarele asocieri sunt fundamentate morfoclinic la dinții permanenți imaturi?","options":[{"id":"A","text":"În pulpita purulentă totală, eliberarea secreției purulente este urmată de emisia unei hemoragii roșu-deschis."},{"id":"B","text":"În pulpita purulentă totală, manevrele de decompresie prin eliminarea puroiului generează consecutiv o sângerare roșu închis."},{"id":"C","text":"În pulpitele ireversibile cronice, investigația camerei pulpare denotă o sângerare moderată, perfect controlabilă prin procedee hemostatice de rutină."},{"id":"D","text":"În pulpita acută seroasă totală, palparea leziunii provoacă o sângerare roșu-deschis, redusă cantitativ."},{"id":"E","text":"În pulpita purulentă parțială, evacuarea puroiului descoperă apariția unei sângerări roșii."}],"correct":["B","D","E"],"pages":[417],"source":"set-2"},{"id":"set2-wS54UJtz","fingerprint":"56fd0184fa6a1d67","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Care sunt elementele caracteristice identificate la examenul obiectiv și complementar în cazul necrozei pulpare?","options":[{"id":"A","text":"Testele de vitalitate prezintă rezultate pozitive la aplicarea stimulilor termici."},{"id":"B","text":"Percuția în ax prezintă un răspuns negativ."},{"id":"C","text":"Prezența unui miros fetid caracteristic la deschiderea camerei pulpare."},{"id":"D","text":"Camera pulpară este închisă la examinarea prin palpare cu sonda."},{"id":"E","text":"Dispariția translucidității coronare și modificarea culorii dintelui la inspecție."}],"correct":["B","D","E"],"pages":[418],"source":"set-2"},{"id":"set2-O9BxGSHy","fingerprint":"90fd0acceabbb403","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Ce modificări clinice se observă în mod specific la examenul obiectiv în cazul gangrenei pulpare simple?","options":[{"id":"A","text":"Percuția în ax determină o reacție intens pozitivă din partea pacientului."},{"id":"B","text":"Camera pulpară este deschisă la efectuarea palpării cu sonda."},{"id":"C","text":"Existența unor cavități profunde cu dentină ramolită abundentă la inspecție."},{"id":"D","text":"Pulpa prezintă o consistență moale și emană un miros fetid."},{"id":"E","text":"Sensibilitate exacerbată și sângerare abundentă la palparea cu sonda a pulpei."}],"correct":["B","C","D"],"pages":[419],"source":"set-2"},{"id":"set2-XO7SkFtW","fingerprint":"ef06162310f465f5","chapterId":"set-2","subchapterId":"set2-5.04","type":"CS","text":"Care dintre următoarele afirmații descrie un aspect specific al gangrenei pulpare simple în timpul examinării clinice?","options":[{"id":"A","text":"Testele de vitalitate pulpară indică un răspuns prezent, de intensitate redusă."},{"id":"B","text":"Examenul subiectiv indică prezența unei dureri specifice cu caracter pulsatil."},{"id":"C","text":"Inspecția coronară evidențiază exclusiv obturații voluminoase, fără pierdere de substanță dură și fără dentină ramolită."},{"id":"D","text":"Forajul explorator provoacă sângerare abundentă și sensibilitate extremă la intrarea în camera pulpară."},{"id":"E","text":"La palparea cu sonda, camera pulpară este deschisă, iar pulpa are o consistență moale și un miros fetid."}],"correct":["E"],"pages":[418],"source":"set-2"},{"id":"set2-eHj-AdaY","fingerprint":"313af5307840fe00","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Care dintre următoarele elemente clinice sunt caracteristice stadiului endoosos al parodontitei apicale acute?","options":[{"id":"A","text":"Dureri de intensitate mare, spontane, exacerbate de masticație, iradiate."},{"id":"B","text":"Mobilitate dentară crescută."},{"id":"C","text":"Senzație de egresiune a dintelui."},{"id":"D","text":"Dureri de intensitate mai mică față de stadiul exteriorizat."},{"id":"E","text":"Percuție în ax negativă sau ușoară jenă."}],"correct":["A","B","C"],"pages":[419],"source":"set-2"},{"id":"set2-ZGOr-TF5","fingerprint":"31f3418b3b268291","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Ce caracteristici prezintă parodontita apicală cronică la examenele clinice și complementare?","options":[{"id":"A","text":"Radiografia relevă prezența unei zone de osteită periapicală."},{"id":"B","text":"Testele de vitalitate furnizează rezultate negative."},{"id":"C","text":"Durerea este severă, iradiată, fără posibilitate de remisiune."},{"id":"D","text":"Pulpa dentară este mortificată, fetidă, fără sensibilitate și sângerare la palpare."},{"id":"E","text":"Percuția în ax este intens pozitivă în mod constant."}],"correct":["A","B","D"],"pages":[419],"source":"set-2"},{"id":"set2-vBgUG6bD","fingerprint":"988877102d260af3","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Care sunt semnele clinice specifice stadiului exteriorizat (abces) al parodontitei apicale acute?","options":[{"id":"A","text":"Dureri de intensitate mai mare comparativ cu stadiul endoosos."},{"id":"B","text":"Percuție în ax intens pozitivă."},{"id":"C","text":"Pulpă mortificată, de consistență moale și cu miros fetid."},{"id":"D","text":"Cameră pulpară închisă, cu pulpă indoloră și sângerândă."},{"id":"E","text":"Dureri spontane, exacerbate de masticație, de intensitate mai mică."}],"correct":["B","C","E"],"pages":[419],"source":"set-2"},{"id":"set2-6XIQy2gf","fingerprint":"06091fa1d83c95ff","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Ce rezultate se obțin la efectuarea percuției în ax și a testelor de vitalitate în formele de parodontită apicală?","options":[{"id":"A","text":"Acutizarea parodontitei apicale cronice determină transformarea percuției în ax într-una pozitivă."},{"id":"B","text":"Parodontita apicală cronică se asociază cu o percuție în ax negativă sau cu senzația de ușoară jenă."},{"id":"C","text":"Efectuarea testelor de vitalitate este obligatorie în fazele de acutizare ale parodontitei cronice."},{"id":"D","text":"În stadiul endoosos al parodontitei apicale acute, percuția în ax este pozitivă, manevra generând durere intensă."},{"id":"E","text":"Testele de vitalitate indică un răspuns intens pozitiv în parodontita apicală cronică."}],"correct":["A","B","D"],"pages":[419],"source":"set-2"},{"id":"set2-bjF6_s9X","fingerprint":"5a197fc206b96ef3","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Care dintre următoarele intervenții terapeutice au rolul de a stimula apexogeneza?","options":[{"id":"A","text":"Pulpectomia non-vitală"},{"id":"B","text":"Coafajele pulpare"},{"id":"C","text":"Pulpotomia vitală parțială sau totală"},{"id":"D","text":"Pulpectomia vitală parțială"},{"id":"E","text":"Apexificarea"}],"correct":["B","C","D"],"pages":[420],"source":"set-2"},{"id":"set2-JJzFAayB","fingerprint":"00265a42b73b98c6","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Care sunt proprietățile medicației de elecție, reprezentată de Ca(OH)₂ și MTA, utilizate în tehnicile ce vizează apexogeneza?","options":[{"id":"A","text":"Proprietăți antiseptice"},{"id":"B","text":"Proprietăți antialgice"},{"id":"C","text":"Proprietăți biostimulatoare"},{"id":"D","text":"Proprietăți necrozante asupra pulpei restante"},{"id":"E","text":"Proprietăți de inhibare a formării periapicale"}],"correct":["A","B","C"],"pages":[420],"source":"set-2"},{"id":"set2-Tmup5lD3","fingerprint":"0d2d1d7483ce02b9","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Ce trăsături definesc procedura de apexificare la dinții permanenți imaturi?","options":[{"id":"A","text":"Se bazează pe stimularea terapeutică a pulpei vii sănătoase restante."},{"id":"B","text":"Se realizează în lipsa creșterii rădăcinii."},{"id":"C","text":"Reprezintă procesul fiziologic de creștere a rădăcinii și de închidere a apexului."},{"id":"D","text":"Se adresează dinților cu necroză, gangrenă pulpară totală simplă sau complicată, fără resturi pulpare vii apicale."},{"id":"E","text":"Creează o barieră apicală din țesut osos, dentină, cement sau țesut conjunctiv fibros."}],"correct":["B","D","E"],"pages":[420],"source":"set-2"},{"id":"set2-M2f5zzfE","fingerprint":"c1594c2a6ed7f0ff","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Dintre metodele de tratament pulpar recomandate pentru dinții permanenți imaturi, care reprezintă variante recunoscute de coafaj pulpar?","options":[{"id":"A","text":"Coafajul indirect"},{"id":"B","text":"Coafajul natural"},{"id":"C","text":"Coafajul non-vital"},{"id":"D","text":"Coafajul direct"},{"id":"E","text":"Coafajul artificial"}],"correct":["A","B","D"],"pages":[420],"source":"set-2"},{"id":"set2-AhFtMAJW","fingerprint":"8b3618cedbd1bf86","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"În ce condiții clinice are loc procesul de apexogeneză?","options":[{"id":"A","text":"La dinții permanenți imaturi sănătoși."},{"id":"B","text":"La dinții cu complicații pulpare, pe baza pulpei vii sănătoase restante și stimulate terapeutic."},{"id":"C","text":"La dinții cu gangrenă pulpară complicată fără resturi pulpare vii apicale."},{"id":"D","text":"Atunci când se creează o barieră apicală exclusiv din os și cement."},{"id":"E","text":"La dinții permanenți imaturi cu necroză pulpară totală."}],"correct":["A","B"],"pages":[420],"source":"set-2"},{"id":"set2-AYFnTep_","fingerprint":"0a0ead1020742aa2","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Care sunt semnele care marchează succesul terapeutic în cazul unui coafaj indirect la dinții permanenți imaturi?","options":[{"id":"A","text":"Formarea unei punți dentinare sub materialul de coafaj vizibilă radiologic după 1-6 luni"},{"id":"B","text":"Păstrarea vitalității pulpare"},{"id":"C","text":"Depunerea de dentină de reparație vizibilă pe radiografie după 6-8 săptămâni"},{"id":"D","text":"Absența simptomelor clinice și radiologice de patologie periapicală"},{"id":"E","text":"Prezența unor focare mici de resorbție internă la nivel coronar"}],"correct":["B","C","D"],"pages":[420,421],"source":"set-2"},{"id":"set2-P3YOihxE","fingerprint":"45df3c2e7a4efbda","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Ce particularități definesc coafajul natural și indicațiile sale în tratamentul dinților permanenți imaturi?","options":[{"id":"A","text":"Metoda implică îndepărtarea dentinei alterate restante după minimum 6-8 săptămâni, în una sau mai multe ședințe."},{"id":"B","text":"Se indică la dinții vitali cu pulpită ireversibilă simptomatică."},{"id":"C","text":"Constă în acoperirea cu hidroxid de calciu a unui perete dentinar profund întrerupt de o cantitate mică de dentină alterată."},{"id":"D","text":"Medicația de elecție este reprezentată atât de hidroxidul de calciu, cât și de MTA."},{"id":"E","text":"Se aplică exclusiv în cazul dinților cu o deschidere punctiformă a camerei pulpare."}],"correct":["A","C"],"pages":[420,421],"source":"set-2"},{"id":"set2-6sz_nQnn","fingerprint":"f931b7db902bfacf","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Care sunt indicațiile coafajului direct la dinții permanenți imaturi?","options":[{"id":"A","text":"Pulpită reversibilă la primul puseu, fără deschiderea camerei pulpare, cu dentină alterată restantă."},{"id":"B","text":"Carii simple profunde cu deschiderea accidentală, iatrogenă, a camerei pulpare."},{"id":"C","text":"Deschidere traumatică de peste 2 mm, cu traumatisme parodontale asociate."},{"id":"D","text":"Pulpită reversibilă în stadiu de debut, cu un istoric de 1-2 pusee dureroase."},{"id":"E","text":"Deschidere traumatică punctiformă sub 1 mm, în traumatisme dentare produse în urmă cu 1-6 ore."}],"correct":["B","D","E"],"pages":[420,421],"source":"set-2"},{"id":"set2-5DZGlvMS","fingerprint":"6384268f53da46c7","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Care afirmații sunt corecte referitor la mecanismele și criteriile de succes ale coafajului direct?","options":[{"id":"A","text":"Radiografia evidențiază formarea unei punți dentinare sub hidroxidul de calciu după 1-6 luni de la intervenție."},{"id":"B","text":"Apariția resorbției interne reprezintă un semn al evoluției clinice favorabile."},{"id":"C","text":"Puntea dentinară formată sub materialul de coafaj se evaluează radiologic la 6-8 săptămâni."},{"id":"D","text":"Răspunsul normal pozitiv la testele de vitalitate confirmă păstrarea vitalității pulpare."},{"id":"E","text":"Iritațiile provenite de la carie sau de la materialul de coafaj pot determina diferențierea celulelor mezenchimale în osteoclaste."}],"correct":["A","D","E"],"pages":[420,421],"source":"set-2"},{"id":"set2-F5sg0sCE","fingerprint":"b8ac5bfa5f8ec000","chapterId":"set-2","subchapterId":"set2-5.04","type":"CS","text":"În cazul coafajului natural la dinții permanenți imaturi, la ce interval minim de timp se recomandă reintervenția pentru îndepărtarea dentinei alterate restante prin tehnica excavațiilor succesive?","options":[{"id":"A","text":"După minimum 2-4 săptămâni"},{"id":"B","text":"După apariția calcificărilor pulpare difuze"},{"id":"C","text":"După minimum 6-8 săptămâni"},{"id":"D","text":"După 1-6 luni"},{"id":"E","text":"După 24-48 de ore"}],"correct":["C"],"pages":[420,421],"source":"set-2"},{"id":"set2-u9Nad9yo","fingerprint":"72dcb740e983299e","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Care dintre următoarele reprezintă indicații ale pulpotomiei vitale parțiale la dinții permanenți imaturi?","options":[{"id":"A","text":"Deschidere pulpară carioasă de 1-2 mm la care sângerarea pulpară poate fi controlată în 1-2 minute."},{"id":"B","text":"Traumatisme cu deschidere a camerei pulpare mai mare de 2 mm sau cu o vechime de 6-10 ore."},{"id":"C","text":"Deschidere pulpară traumatică asociată cu inflamație cronică parțială a pulpei coronare limitată la 1-3 mm."},{"id":"D","text":"Dinți permanenți imaturi cu eșec după coafaje."},{"id":"E","text":"Indiferent de vechimea traumatismului și mărimea deschiderii, dacă hemostaza se obține în maxim 1-2 minute după îndepărtarea țesutului inflamat."}],"correct":["A","C","E"],"pages":[422],"source":"set-2"},{"id":"set2-VCx05Ydj","fingerprint":"9edefc128a70724b","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Care dintre următoarele situații reprezintă contraindicații pentru realizarea pulpotomiei vitale totale la un dinte permanent imatur?","options":[{"id":"A","text":"Prezența calcificărilor pulpare sau a perforației interradiculare."},{"id":"B","text":"Semne de pulpită ireversibilă sau necroză pulpară."},{"id":"C","text":"Distrucție coronară mai mică de 2/3 din volumul inițial."},{"id":"D","text":"Pacienți cu reumatism poliarticular acut sau malformații congenitale."},{"id":"E","text":"Eșec în urma coafajelor anterioare."}],"correct":["A","B","D"],"pages":[423],"source":"set-2"},{"id":"set2-5QWsTJ2M","fingerprint":"47c8abda5302e4ed","chapterId":"set-2","subchapterId":"set2-5.04","type":"CS","text":"Care este descrierea unui aspect tehnic sau a unui criteriu de succes în cazul pulpotomiei vitale totale la dinții permanenți imaturi?","options":[{"id":"A","text":"Excizia pulpei coronare se realizează până la joncțiunea smalț-cement, iar hemostaza trebuie să se obțină în 1-3 minute."},{"id":"B","text":"Se utilizează anestezie plexală cu vasoconstrictor pentru a facilita hemostaza rapidă."},{"id":"C","text":"Un criteriu de succes radiologic este oprirea creșterii rădăcinii pentru a preveni resorbția radiculară patologică."},{"id":"D","text":"Peste plaga pulpară se aplică un strat izolator de eugenat de zinc urmat de obturație provizorie."},{"id":"E","text":"Pentru excizie se folosește exclusiv o freză diamantată sferică mică la turație mare."}],"correct":["A"],"pages":[423],"source":"set-2"},{"id":"set2-59MMweKX","fingerprint":"b9cf238d99a885a2","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Care sunt particularitățile tehnicilor de pulpotomie vitală parțială și totală aplicate la dinții permanenți imaturi?","options":[{"id":"A","text":"Ambele tehnici utilizează anestezie plexală fără vasoconstrictor."},{"id":"B","text":"Medicația de elecție aplicată pe plaga pulpară în ambele cazuri este reprezentată de hidroxid de calciu sau MTA."},{"id":"C","text":"Ambele proceduri necesită ca hemostaza să fie obținută în maxim 5 minute după irigarea cu ser fiziologic."},{"id":"D","text":"La pulpotomia parțială se îndepărtează 1-3 mm de pulpă, pe când la cea totală excizia se face până la joncțiunea smalț-cement."},{"id":"E","text":"Pulpotomia totală este indicată la pacienții cu boli cronice, cum ar fi diabetul, pentru a stimula vindecarea periapicală."}],"correct":["A","B","D"],"pages":[423],"source":"set-2"},{"id":"set2-wSzUyVoR","fingerprint":"3afd9b8ee517215b","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Care sunt criteriile ce marchează succesul pulpotomiei vitale parțiale la dinții permanenți imaturi?","options":[{"id":"A","text":"Evidențierea apariției unei bariere de dentină de reparație sub preparatul de hidroxid de calciu."},{"id":"B","text":"Continuarea creșterii rădăcinii și închiderea apexului (apexogeneza) vizibile radiologic."},{"id":"C","text":"Evidențierea radiologică a unui grad ușor de patologie interradiculară asimptomatică."},{"id":"D","text":"Absența simptomatologiei clinice."},{"id":"E","text":"Insensibilizarea pulpei restante prin menținerea inflamației cronice pe o profunzime de 1-3 mm."}],"correct":["A","B","D"],"pages":[423],"source":"set-2"},{"id":"set2-7AylQMnf","fingerprint":"3e33cf20258a4736","chapterId":"set-2","subchapterId":"set2-5.04","type":"CS","text":"Referitor la tehnica pulpectomiei vitale parțiale la dinții permanenți imaturi, care sunt etapele și procedurile specifice?","options":[{"id":"A","text":"Lărgirea canalului radicular reprezintă o etapă esențială pentru succesul procedurii."},{"id":"B","text":"Se lasă un bont radicular viu cu o lungime de 6-8 mm."},{"id":"C","text":"Pulpa radiculară se îndepărtează cu ace Hedström subțiri, cu vârf ascuțit."},{"id":"D","text":"Anestezia plexală sau tronculară periferică se efectuează obligatoriu cu vasoconstrictor."},{"id":"E","text":"Hemoragia trebuie să se oprească în aproximativ 10-15 minute în urma irigării cu ser fiziologic."}],"correct":["B"],"pages":[423],"source":"set-2"},{"id":"set2-1de3A0kK","fingerprint":"3976b6ca0888819b","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Care dintre următoarele situații clinice reprezintă indicații pentru efectuarea pulpectomiei vitale parțiale la dinții permanenți imaturi?","options":[{"id":"A","text":"Inflamația pulpară extinsă dincolo de pulpa coronară, fără semne radiologice de afectare a parodonțiului periradicular."},{"id":"B","text":"Inflamația pulpară extinsă dincolo de pulpa coronară, în prezența semnelor radiologice de afectare periradiculară."},{"id":"C","text":"Prezența pulpitei ireversibile la un dinte restaurabil."},{"id":"D","text":"Prezența gangrenei pulpare simple."},{"id":"E","text":"Existența unui eșec în urma unei proceduri de pulpotomie la un dinte vital."}],"correct":["A","C","E"],"pages":[423],"source":"set-2"},{"id":"set2-5t7Vp1bQ","fingerprint":"25a9b81c5b4c18da","chapterId":"set-2","subchapterId":"set2-5.04","type":"CS","text":"Ce mecanisme și fenomene fiziologice stau la baza succesului pulpectomiei vitale parțiale în cazul dinților permanenți imaturi?","options":[{"id":"A","text":"Zona pulpară terminală a rădăcinii este dependentă funcțional de restul pulpei, compromiterea acesteia ducând inevitabil la oprirea dezvoltării."},{"id":"B","text":"Închiderea apexului se realizează prin formarea unei bariere de țesut osos la nivelul treimii medii a canalului radicular."},{"id":"C","text":"Zona pulpară terminală a rădăcinii este lipsită de vascularizație pentru a preveni difuzarea inflamației."},{"id":"D","text":"Potențialul celular activ din regiunea apicală contribuie exclusiv la creșterea în grosime a treimii cervicale a rădăcinii."},{"id":"E","text":"Regiunea apicală largă prezintă un potențial celular activ care participă la creșterea în lungime și grosime a treimii apicale a rădăcinii și la închiderea apexului."}],"correct":["E"],"pages":[423],"source":"set-2"},{"id":"set2-w-MfXKmu","fingerprint":"232fdf701a6acdf6","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Care sunt caracteristicile procedurii de pulpectomie non-vitală la dinții permanenți imaturi?","options":[{"id":"A","text":"Este urmată fie de apexificare, fie de revascularizare pentru a permite închiderea apexului."},{"id":"B","text":"Presupune instrumentarea mecanică a canalelor și sterilizarea spațiului endodontic."},{"id":"C","text":"Reprezintă o metodă de tratament indicată doar la pacienții care se pot prezenta la o singură ședință terapeutică."},{"id":"D","text":"Presupune îndepărtarea pulpei coronare și a unei părți din pulpa radiculară insensibilizate prin anestezie."},{"id":"E","text":"Este indicată la dinții permanenți imaturi care întrețin complicații infecțioase majore."}],"correct":["A","B"],"pages":[424],"source":"set-2"},{"id":"set2-wwQOFQ4V","fingerprint":"6240865968da0d46","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Care dintre următoarele criterii marchează succesul terapeutic în cazul pulpectomiei vitale parțiale la dinții permanenți imaturi?","options":[{"id":"A","text":"Lipsa mobilității anormale a dintelui."},{"id":"B","text":"Absența complicațiilor periapicale și dispariția simptomelor."},{"id":"C","text":"Menținerea unei mobilități dentare crescute pentru a permite acomodarea funcțională a parodonțiului."},{"id":"D","text":"Creșterea rădăcinii în lungime și grosime concomitent cu închiderea apexului."},{"id":"E","text":"Prezența unei percuții în ax pozitive ca răspuns fiziologic la vindecarea tisulară."}],"correct":["A","B","D"],"pages":[424],"source":"set-2"},{"id":"set2-wwIow0Tx","fingerprint":"30baf56d0713a309","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Care sunt afirmațiile adevărate privind mecanismul și consecințele morfologice ale procesului de apexificare la dinții permanenți imaturi?","options":[{"id":"A","text":"Modelarea apexului se realizează pe baza țesutului conjunctiv periapical tânăr, chiar în absența pulpei vii."},{"id":"B","text":"Țesutul periapical tânăr conține exclusiv celule producătoare de dentină."},{"id":"C","text":"Teaca lui Hertwig își menține funcționalitatea, permițând creșterea în lungime a rădăcinii."},{"id":"D","text":"Grosimea pereților laterali radiculari și lungimea totală a rădăcinii rămân nemodificate la finalul tratamentului."},{"id":"E","text":"Forma apicală rezultată în urma apexificării este uniformă, cel mai frecvent ascuțită."}],"correct":["A","D"],"pages":[424],"source":"set-2"},{"id":"set2-jLSS7U8m","fingerprint":"c239a1be665cc22f","chapterId":"set-2","subchapterId":"set2-5.04","type":"CS","text":"Care este implicația clinico-terapeutică majoră a apexului larg, fără stop apical, în realizarea procedurii de apexificare?","options":[{"id":"A","text":"Dificultatea majoră în evacuarea completă a conținutului mortificat și infectat al canalului."},{"id":"B","text":"Predispoziția la frecvente fracturi radiculare verticale și cervicale."},{"id":"C","text":"Necesitatea calibrării și lărgirii extensive a canalului pentru obținerea stopului apical."},{"id":"D","text":"Riscul de depășire periapicală a obturației de canal, ceea ce scade rata succesului terapeutic."},{"id":"E","text":"Modificarea nefavorabilă a proporției coroană/rădăcină."}],"correct":["D"],"pages":[425],"source":"set-2"},{"id":"set2-V6DMLaRX","fingerprint":"b5591f93ebe3b9ad","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Care dintre următoarele substanțe pot fi utilizate în amestec cu hidroxidul de calciu (Ca(OH)₂) pentru realizarea apexificării?","options":[{"id":"A","text":"Soluția Walkhoff"},{"id":"B","text":"Acetatul de metacresil (Cresatin)"},{"id":"C","text":"Serul fiziologic"},{"id":"D","text":"Rășinile compozite fluide"},{"id":"E","text":"Cimentul ionomer de sticlă"}],"correct":["A","B","C"],"pages":[425],"source":"set-2"},{"id":"set2--Z3HkPlt","fingerprint":"714880c17b57c830","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Care sunt afirmațiile adevărate referitoare la apexificarea cu MTA comparativ cu apexificarea pe bază de hidroxid de calciu (Ca(OH)₂)?","options":[{"id":"A","text":"Lipsa creșterii radiculare și a îngroșării pereților dentinari determină un risc crescut de fracturi radiculare pentru ambele tehnici."},{"id":"B","text":"Apexificarea cu MTA necesită un număr crescut de reintervenții pe canal pentru înlocuirea materialului resorbit."},{"id":"C","text":"Bariera apicală se obține mult mai repede în cazul utilizării MTA, tratamentul presupunând două ședințe."},{"id":"D","text":"Apexificarea cu MTA este cea mai veche și cea mai simplă metodă de tratament a dinților permanenți imaturi."},{"id":"E","text":"Ambele metode induc formarea unei bariere apicale care oferă suport pentru obturația definitivă de canal."}],"correct":["A","C","E"],"pages":[426],"source":"set-2"},{"id":"set2-3s7z51pp","fingerprint":"14c7b57146060a2c","chapterId":"set-2","subchapterId":"set2-5.04","type":"CS","text":"Care dintre următoarele constituie un obiectiv al tratamentului prin apexificare?","options":[{"id":"A","text":"Reluarea funcționalității tecii lui Hertwig."},{"id":"B","text":"Creșterea grosimii pereților laterali radiculari."},{"id":"C","text":"Prevenirea apariției resorbției radiculare."},{"id":"D","text":"Menținerea apexului deschis pentru drenaj pe termen lung."},{"id":"E","text":"Obținerea de țesut pulpar vital la nivelul treimii apicale."}],"correct":["C"],"pages":[424],"source":"set-2"},{"id":"set2-9UNfSJxG","fingerprint":"a53104dc0a299faa","chapterId":"set-2","subchapterId":"set2-5.04","type":"CS","text":"Care dintre următoarele afirmații descrie corect principiile de revascularizare (terapia endodontică de regenerare) a dinților permanenți imaturi?","options":[{"id":"A","text":"Cheagul sanguin format acționează ca o matrice pentru regenerarea țesutului pulpar."},{"id":"B","text":"Materialul de elecție aplicat direct peste cheag înainte de sigilarea coronară este hidroxidul de calciu."},{"id":"C","text":"Dezinfecția canalului necesită o instrumentare mecanică extensivă însoțită de irigații."},{"id":"D","text":"Sângerarea este inițiată pentru a umple canalul până deasupra joncțiunii smalț-cement cu 3 mm."},{"id":"E","text":"Se efectuează o pulpectomie vitală."}],"correct":["A"],"pages":[426],"source":"set-2"},{"id":"set2-B9zSMEK5","fingerprint":"dd26a9517519645e","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Care sunt avantajele revascularizării (terapiei endodontice de regenerare) în tratamentul dinților permanenți imaturi?","options":[{"id":"A","text":"Subțierea pereților radiculari pentru a facilita proliferarea tisulară celulară."},{"id":"B","text":"Determinarea creșterii rădăcinii și închiderea apexului."},{"id":"C","text":"Permite finalizarea întregului tratament într-o singură ședință clinică."},{"id":"D","text":"Este o procedură cu risc scăzut de complicații în comparație cu metoda chirurgicală."},{"id":"E","text":"Reprezintă o intervenție nestresantă și neinvazivă."}],"correct":["B","D","E"],"pages":[426],"source":"set-2"},{"id":"set2-bezN61k2","fingerprint":"600b99fc2f0cd094","chapterId":"set-2","subchapterId":"set2-5.04","type":"CM","text":"Care sunt etapele specifice incluse în descrierea tehnicii de revascularizare a dinților permanenți imaturi?","options":[{"id":"A","text":"Utilizarea instrumentarului rotativ mecanic la nivelul întregului canal pentru a asigura curățarea optimă a pereților."},{"id":"B","text":"Iritarea mecanică a apexului pentru a iniția sângerarea din zona periapicală."},{"id":"C","text":"Efectuarea unei pulpectomii nonvitale."},{"id":"D","text":"Sigilarea etanșă a accesului coronar după aplicarea MTA-ului."},{"id":"E","text":"Aplicarea unei paste cu o combinație de trei antibiotice în interiorul canalului radicular."}],"correct":["B","C","D","E"],"pages":[426],"source":"set-2"}];
